const unwrap = (res) => {
  if (Array.isArray(res)) return res;
  if (Array.isArray(res?.data)) return res.data;

  // Support common API response wrappers such as:
  // { data: { roles: [...] } }, { roles: [...] }, etc.
  const container = res?.data && typeof res.data === "object"
    ? res.data
    : res;

  if (Array.isArray(container?.items)) return container.items;
  if (Array.isArray(container?.results)) return container.results;
  if (Array.isArray(container?.data)) return container.data;
  if (Array.isArray(container?.departments)) return container.departments;
  if (Array.isArray(container?.roles)) return container.roles;
  if (Array.isArray(container?.shifts)) return container.shifts;
  if (Array.isArray(container?.classes)) return container.classes;
  if (Array.isArray(container?.subjects)) return container.subjects;
  if (Array.isArray(container?.employees)) return container.employees;
  if (Array.isArray(container?.managers)) return container.managers;

  return [];
};

