                        <SelectTrigger>
                          <SelectValue
                            placeholder={
                              refLoading ? "Loading..." : "Select class"
                            }
                          />
                        </SelectTrigger>
                        <SelectContent>
                          {ref.classes.map((c) => {
                            const value = firstOf(c, [
                              "class_uuid",
                              "uuid",
                              "id",
                            ]);
