                  <DocumentUploadCard
                    key={docType}
                    docType={docType}
                    label={docLabel}
                    hint={`PDF / JPG / PNG · max ${MAX_FILE_MB} MB`}
                    file={docFiles[docType] || null}
                    existingDoc={existingDoc}
                    disabled={!supportedInEditMode}
                    onFileSelect={(file) => handleFileChange(docType, file)}
                    onRemove={() =>
                      setDocFiles((prev) => {
