                    </span>
                  ) : reviewData ? (
                    <Badge
                      variant="outline"
                      className={`shrink-0 ${
                        reviewData.review_completed
                          ? "bg-success/10 text-success border-success/20"
                          : "bg-destructive/10 text-destructive border-destructive/20"
                      }`}
                    >
                      <ClipboardCheck className="h-3.5 w-3.5 mr-1" />
