            <F label="Blood Group" error={errors.blood}>
              <Select value={f.blood} onValueChange={(v) => set("blood", v)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select" />
                </SelectTrigger>
                <SelectContent>
                  {BLOOD_GROUPS.map((x) => (
                    <SelectItem key={x} value={x}>
                      {x}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </F>
            <F label="Student Aadhar" error={errors.aadhar}>
              <Input
                value={f.aadhar}
