      section_uuid: student.section_uuid,
      rollNo: student.roll_no,
      stream: student.stream,
      session: student.session_year,
    }));

    setStudents(mapped);
  } catch (err) {
    console.error(err);
    toast.error("Failed to fetch students");
  } finally {
