// ================= Departments Tab =================
function DepartmentsTab() {
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(false);

  const [open, setOpen] = useState(false);
  const [edit, setEdit] = useState(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [status, setStatus] = useState("ACTIVE");
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  const [subjectList, setSubjectList] = useState([]);

 const fetchDepartments = async () => {
  try {
    setLoading(true);
    const res = await getDepartments();
    setDepartments(res || []);   // ✅ res is already the array
  } catch (err) {
    console.error(err);
    toast.error("Failed to fetch departments");
  } finally {
    setLoading(false);
  }
};

  useEffect(() => {
    fetchDepartments();
    getSubjects()
      .then((res) => setSubjectList(res.data || []))
      .catch((err) => console.error(err));
  }, []);

  const departmentsPage = usePagination(departments, 10);

  const reset = () => {
    setName("");
    setDescription("");
    setStatus("ACTIVE");
    setErrors({});
    setEdit(null);
  };

  const openNew = () => {
    reset();
    setOpen(true);
  };

 const openEdit = async (d) => {
  try {
    setLoading(true);
    const res = await getDepartmentByUUID(d.department_uuid);
    const dept = res;   // ✅ was res.data
    setEdit(dept);
    setName(dept.department_name ?? "");
    setDescription(dept.description ?? "");
    setStatus(dept.status ?? "ACTIVE");
    setErrors({});
    setOpen(true);
  } catch (err) {
    console.error(err);
    toast.error("Failed to load department");
  } finally {
    setLoading(false);
  }
};

 const save = async () => {
  const clientErrors = validateDepartmentForm(
    { name },
    departments,
    edit?.department_uuid ?? null,
  );
  if (Object.keys(clientErrors).length > 0) {
    setErrors(clientErrors);
    return;
  }
  setErrors({});

    const payload = {
      department_name: name.trim(),
      description: description.trim() || null,
      status,
    };

    setSubmitting(true);
    try {
      if (edit) {
        await updateDepartment(edit.department_uuid, payload);
        toast.success(`${name} updated`);
      } else {
        await createDepartment(payload);
        toast.success(`${name} created`);
      }
      fetchDepartments();
      setOpen(false);
      reset();
    } catch (err) {
      console.error(err);
      const apiErrors = mapApiErrorToDepartmentFieldErrors(err);
      if (Object.keys(apiErrors).length > 0) {
        setErrors(apiErrors);
      } else {
        toast.error(
          err?.response?.data?.message ||
            (edit ? "Failed to update department" : "Failed to create department"),
        );
      }
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (d) => {
    try {
      await deleteDepartment(d.department_uuid);
      toast.success(`${d.department_name} removed`);
      fetchDepartments();
    } catch (err) {
      console.error(err);
      toast.error(err?.response?.data?.message || "Failed to delete department");
    }
  };

  const subjectsForDept = (d) =>
    subjectList.filter((s) => s.department === d.department_name);

  return (
    <div className="space-y-4">
      <Card className="border-border/60">
        <CardHeader className="flex-row items-center justify-between space-y-0">
          <div>
            <CardTitle className="text-base">Departments</CardTitle>
           
          </div>
          <div className="flex items-center gap-2">
            <RowsPerPageSelect {...departmentsPage} />
            <Button size="sm" className="gradient-primary border-0" onClick={openNew}>
              <Plus className="h-4 w-4" /> New Department
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Department</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Description</TableHead>
                <TableHead className="w-24 text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {!loading && departments.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} className="text-center text-sm text-muted-foreground py-8">
                    No departments yet.
                  </TableCell>
                </TableRow>
              )}
              {departmentsPage.pageItems.map((d) => {
                const subs = subjectsForDept(d);
                return (
                  <TableRow key={d.department_uuid}>
                    <TableCell className="font-medium">{d.department_name}</TableCell>
                    <TableCell>
                      <Badge variant={d.status === "ACTIVE" ? "default" : "outline"}>
                        {d.status}
                      </Badge>
                    </TableCell>
                    <TableCell
                      className="text-xs text-muted-foreground max-w-xs truncate"
                      title={d.description}
                    >
                      {d.description || "—"}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button size="sm" variant="ghost" onClick={() => openEdit(d)}>
                        <Pencil className="h-3.5 w-3.5" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        className="text-destructive"
                        onClick={() => handleDelete(d)}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
          <PaginationBar {...departmentsPage} itemLabel="departments" showPageSize={false} />
        </CardContent>
      </Card>

      <Dialog
        open={open}
        onOpenChange={(o) => {
          setOpen(o);
          if (!o) reset();
        }}
      >
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{edit ? "Edit Department" : "New Department"}</DialogTitle>
          </DialogHeader>
          <div className="grid gap-3">
            <div>
<Label className="text-xs">
  Name <span className="text-destructive">*</span>
</Label>
              <Input
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  if (errors.name) setErrors((p) => ({ ...p, name: undefined }));
                }}
                placeholder="e.g. Mathematics"
                className={
                  errors.name ? "border-destructive focus-visible:ring-destructive" : ""
                }
              />
              {errors.name && (
                <p className="text-xs text-destructive flex items-center gap-1 mt-1">
                  <AlertTriangle className="h-3 w-3" />
                  {errors.name}
                </p>
              )}
            </div>
            <div>
              <Label className="text-xs">Description</Label>
              <Textarea rows={2} value={description} onChange={(e) => setDescription(e.target.value)} />
            </div>
            <div>
              <Label className="text-xs">Status</Label>
              <Select value={status} onValueChange={setStatus}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ACTIVE">Active</SelectItem>
                  <SelectItem value="INACTIVE">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)} disabled={submitting}>
              Cancel
            </Button>
            <Button className="gradient-primary border-0" onClick={save} disabled={submitting}>
              {submitting ? "Saving..." : edit ? "Save" : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ================= Section Dialog =================
function SectionDialog({ open, onOpenChange, edit, sections = [], onSubmit }) {
  const [classOptions, setClassOptions] = useState([]);
  const [roomOptions, setRoomOptions] = useState([]);
  const [teacherOptions, setTeacherOptions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState({});
   const [form, setForm] = useState({
    name: "",
    class_uuid: "",
    teacher: "",
    otherTeachers: [],
    room_uuid: "",
    room: "",
    present: 0,
    total: 40,
  });

  useEffect(() => {
    if (!open) return;

       setForm({
      name: edit?.section_name ?? "",
      class_uuid: edit?.class_uuid ?? "",
      teacher: edit?.class_teacher_employee_uuid ?? "",
      otherTeachers: edit?.other_teacher_employee_uuids ?? [],
      room_uuid: edit?.room_uuid ?? "",
      room: edit?.room ?? "",
      present: edit?.current_students ?? 0,
      total: edit?.capacity ?? 40,
    });
    setErrors({});

    const loadData = async () => {
      setLoading(true);
      try {
        const [classesRes, roomsRes] = await Promise.all([
          getClasses(),
          getRooms(),
        ]);
        setClassOptions(classesRes.data || []);
        setRoomOptions(
          (roomsRes.data || []).map((room) => ({
            value: room.room_uuid,
            label: room.display_label,
          })),
        );
      } catch (err) {
        console.error(err);
        toast.error("Failed to load classes/rooms");
      } finally {
        setLoading(false);
      }
    };
    loadData();

    if (edit?.class_uuid) {
      getClassFaculty(edit.class_uuid)
        .then((res) => setTeacherOptions(res.data || []))
        .catch((err) => {
          console.error(err);
          setTeacherOptions([]);
        });
    } else {
      setTeacherOptions([]);
    }
  }, [open, edit]);

  const clearError = (field) =>
    setErrors((p) => (p[field] ? { ...p, [field]: undefined } : p));

   const handleClassChange = async (classUUID) => {
    setForm((prev) => ({ ...prev, class_uuid: classUUID, teacher: "", otherTeachers: [] }));
    clearError("class_uuid");
    try {
      const res = await getClassFaculty(classUUID);
      setTeacherOptions(res.data || []);
    } catch (err) {
      console.error(err);
      setTeacherOptions([]);
    }
  };

    const classTeacherOptions = teacherOptions.filter(
    (t) => !form.otherTeachers.includes(t.employee_uuid),
  );
  const otherTeacherOptions = teacherOptions.filter(
    (t) => t.employee_uuid !== form.teacher,
  );

  const submit = async () => {
    const clientErrors = validateSectionForm(
      form,
      sections,
      edit?.section_uuid ?? null,
    );
    if (form.present > form.total) {
      clientErrors.present = "Present capacity cannot exceed total capacity.";
    }
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }
    setErrors({});

  const payload = {
  section_name: form.name.trim(),
  class_uuid: form.class_uuid,
  class_teacher_employee_uuid: form.teacher || null,
  other_teacher_employee_uuids: form.otherTeachers,
  room_uuid: form.room_uuid,
  students: form.present,
  capacity: form.total,
  subjects: edit?.subjects ?? 8,
};
    setSubmitting(true);
    try {
      await onSubmit(payload);
    } catch (err) {
      const apiErrors = mapApiErrorToSectionFieldErrors(err);
      if (Object.keys(apiErrors).length > 0) {
        setErrors(apiErrors);
      } else {
        toast.error(err?.response?.data?.message || "Failed to save section");
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
<DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
          <DialogTitle>
            {edit ? "Edit Section" : "Create New Section"}
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3 py-2">
          <div className="space-y-1.5">
            <Label className="text-xs">
              Section Name <span className="text-destructive">*</span>
            </Label>
            <Input
              value={form.name}
              onChange={(e) => {
                setForm((p) => ({ ...p, name: e.target.value }));
                clearError("name");
              }}
              placeholder="e.g. X-B"
              className={
                errors.name
                  ? "border-destructive focus-visible:ring-destructive"
                  : ""
              }
            />
            {errors.name && (
              <p className="text-xs text-destructive flex items-center gap-1">
                <AlertTriangle className="h-3 w-3" />
                {errors.name}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label className="text-xs">
              Class <span className="text-destructive">*</span>
            </Label>
            <Select value={form.class_uuid} onValueChange={handleClassChange}>
              <SelectTrigger
                className={
                  errors.class_uuid
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              >
                <SelectValue
                  placeholder={loading ? "Loading…" : "Pick class"}
                />
              </SelectTrigger>
              <SelectContent>
                {classOptions.map((cls) => (
                  <SelectItem key={cls.class_uuid} value={cls.class_uuid}>
                    {cls.class_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.class_uuid && (
              <p className="text-xs text-destructive flex items-center gap-1">
                <AlertTriangle className="h-3 w-3" />
                {errors.class_uuid}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label className="text-xs">
              Class Teacher 
            </Label>
                       <Select
              value={form.teacher}
              onValueChange={(value) => {
                setForm((p) => ({
                  ...p,
                  teacher: value,
                  otherTeachers: p.otherTeachers.filter((id) => id !== value),
                }));
                clearError("teacher");
              }}
            >
              <SelectTrigger
                className={
                  errors.teacher
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              >
                <SelectValue placeholder="Pick teacher" />
              </SelectTrigger>
          <SelectContent>
  {classTeacherOptions.map((teacher) => (
    <SelectItem
      key={teacher.employee_uuid}
      value={teacher.employee_uuid}
    >
      {teacher.faculty_name}
    </SelectItem>
  ))}
</SelectContent>
            </Select>
            {errors.teacher && (
              <p className="text-xs text-destructive flex items-center gap-1">
                <AlertTriangle className="h-3 w-3" />
                {errors.teacher}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label className="text-xs">Other Teachers</Label>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  className="w-full justify-start font-normal h-9 truncate"
                >
                  {form.otherTeachers.length > 0
                    ? form.otherTeachers
                        .map(
                          (id) =>
                            teacherOptions.find((t) => t.employee_uuid === id)
                              ?.faculty_name,
                        )
                        .filter(Boolean)
                        .join(", ")
                    : "Select Teachers"}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-64 p-2" align="start">
                <div className="max-h-48 overflow-y-auto space-y-1">
                  {otherTeacherOptions.length === 0 && (
                    <div className="text-xs text-muted-foreground py-2 text-center">
                      No other teachers available.
                    </div>
                  )}
                  {otherTeacherOptions.map((teacher) => (
                    <label
                      key={teacher.employee_uuid}
                      className="flex items-center gap-2 text-sm cursor-pointer hover:bg-muted/50 rounded px-1.5 py-1"
                    >
                      <Checkbox
                        checked={form.otherTeachers.includes(
                          teacher.employee_uuid,
                        )}
                        onCheckedChange={(checked) => {
                          setForm((p) => ({
                            ...p,
                            otherTeachers: checked
                              ? [...p.otherTeachers, teacher.employee_uuid]
                              : p.otherTeachers.filter(
                                  (id) => id !== teacher.employee_uuid,
                                ),
                          }));
                        }}
                      />
                      <span>{teacher.faculty_name}</span>
                    </label>
                  ))}
                </div>
              </PopoverContent>
            </Popover>
            {form.otherTeachers.length > 0 && (
              <div className="flex flex-wrap gap-1 pt-1">
                {form.otherTeachers.map((id) => {
                  const t = teacherOptions.find(
                    (x) => x.employee_uuid === id,
                  );
                  return (
                    <Badge key={id} variant="secondary" className="text-[10px]">
                      {t ? t.faculty_name : id}
                    </Badge>
                  );
                })}
              </div>
            )}
            {errors.teacher && (
              <p className="text-xs text-destructive flex items-center gap-1">
                <AlertTriangle className="h-3 w-3" />
                {errors.teacher}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label className="text-xs">Room</Label>
            <Select
              value={form.room_uuid}
              onValueChange={(value) => {
                setForm((prev) => ({ ...prev, room_uuid: value }));
                clearError("room_uuid");
              }}
            >
              <SelectTrigger
                className={
                  errors.room_uuid
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              >
                <SelectValue placeholder="Select Room" />
              </SelectTrigger>
              <SelectContent>
                {roomOptions.map((room) => (
                  <SelectItem key={room.value} value={room.value}>
                    {room.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.room_uuid && (
              <p className="text-xs text-destructive flex items-center gap-1">
                <AlertTriangle className="h-3 w-3" />
                {errors.room_uuid}
              </p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Present Capacity</Label>
              <Input
                type="number"
                value={form.present}
                onChange={(e) => {
                  setForm((p) => ({ ...p, present: Number(e.target.value) }));
                  clearError("present");
                }}
                className={
                  errors.present
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              />
              {errors.present && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {errors.present}
                </p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">
                Total Capacity <span className="text-destructive">*</span>
              </Label>
              <Input
                type="number"
                value={form.total}
                onChange={(e) => {
                  setForm((p) => ({ ...p, total: Number(e.target.value) }));
                  clearError("total");
                }}
                className={
                  errors.total
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              />
              {errors.total && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {errors.total}
                </p>
              )}
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={submitting}
          >
            Cancel
          </Button>
          <Button
            className="gradient-primary border-0"
            onClick={submit}
            disabled={submitting}
          >
            {submitting ? "Saving..." : edit ? "Save" : "Create"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ================= Subject Dialog =================
// ================= Subject Dialog =================
function SubjectDialog({
  open,
  onOpenChange,
  edit,
  subjects = [],
  teacherOptions,
  onSubmit,
}) {
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [dept, setDept] = useState("");
  const [type, setType] = useState("Core");
  const [facultyCount, setFacultyCount] = useState(1);
  const [faculties, setFaculties] = useState([]);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!open) return;
    setCode(edit?.subject_code ?? "");
    setName(edit?.subject_name ?? "");
    setDept(edit?.department ?? "");
    setType(edit?.subject_type ?? "Core");
    setFacultyCount(edit?.faculty_count ?? edit?.faculty_employee_uuids?.length ?? 1);
    setFaculties(edit?.faculty_employee_uuids ?? []);
    setErrors({});
  }, [open, edit]);

  const toggleFaculty = (id) =>
    setFaculties((p) =>
      p.includes(id) ? p.filter((x) => x !== id) : [...p, id],
    );

  const submit = async () => {
    const payload = {
      subject_code: code.trim(),
      subject_name: name.trim(),
      department: dept.trim() || "General",
      subject_type: type,
      faculty_count: Math.max(facultyCount, faculties.length),
      faculty_employee_uuids: faculties,
    };

    // Client-side required + duplicate check
    const clientErrors = validateSubjectForm(
      payload,
      subjects,
      edit?.subject_uuid ?? null,
    );
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setErrors({});
    setSubmitting(true);
    try {
      await onSubmit(payload);
    } catch (err) {
      // Server-side duplicate (or other) error — map onto the same fields
      const apiErrors = mapApiErrorToFieldErrors(err);
      if (Object.keys(apiErrors).length > 0) {
        setErrors(apiErrors);
      } else {
        toast.error(
          edit ? "Failed to update subject" : "Failed to create subject",
        );
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {edit ? "Edit Subject" : "Create New Subject"}
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3 py-2">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">
                Subject Code <span className="text-destructive">*</span>
              </Label>
              <Input
                value={code}
                onChange={(e) => {
                  setCode(e.target.value);
                  if (errors.subject_code)
                    setErrors((p) => ({ ...p, subject_code: undefined }));
                }}
                placeholder="e.g. MTH101"
                className={
                  errors.subject_code
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              />
              {errors.subject_code && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {errors.subject_code}
                </p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">
                Subject Name <span className="text-destructive">*</span>
              </Label>
              <Input
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  if (errors.subject_name)
                    setErrors((p) => ({ ...p, subject_name: undefined }));
                }}
                placeholder="e.g. Mathematics"
                className={
                  errors.subject_name
                    ? "border-destructive focus-visible:ring-destructive"
                    : ""
                }
              />
              {errors.subject_name && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {errors.subject_name}
                </p>
              )}
            </div>
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Department</Label>
            <Input
              value={dept}
              onChange={(e) => setDept(e.target.value)}
              placeholder="e.g. Science, Humanities, Engineering"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Type</Label>
              <Select value={type} onValueChange={setType}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {SUBJECT_TYPES.map((t) => (
                    <SelectItem key={t} value={t}>
                      {t}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Faculty Count</Label>
              <Input
                type="number"
                min={0}
                value={facultyCount}
                onChange={(e) => setFacultyCount(Number(e.target.value))}
              />
            </div>
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Choose Faculties (multiple)</Label>
            <div className="rounded-md border max-h-48 overflow-y-auto p-2 space-y-1">
              {teacherOptions.length === 0 && (
                <div className="text-xs text-muted-foreground py-2 text-center">
                  No teachers available.
                </div>
              )}
              {teacherOptions.map((t) => (
                <label
                  key={t.id}
                  className="flex items-center gap-2 text-sm cursor-pointer hover:bg-muted/50 rounded px-1.5 py-1"
                >
                  <Checkbox
                    checked={faculties.includes(t.id)}
                    onCheckedChange={() => toggleFaculty(t.id)}
                  />
                  <span>{t.name}</span>
                </label>
              ))}
            </div>
            {faculties.length > 0 && (
              <div className="flex flex-wrap gap-1 pt-1">
                {faculties.map((f) => {
                  const t = teacherOptions.find((o) => o.id === f);
                  return (
                    <Badge key={f} variant="secondary">
                      {t ? t.name : f}
                    </Badge>
                  );
                })}
              </div>
            )}
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={submitting}
          >
            Cancel
          </Button>
          <Button
            className="gradient-primary border-0"
            onClick={submit}
            disabled={submitting}
          >
            {submitting ? "Saving..." : edit ? "Save" : "Create"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

