      chapter_topic: it.chapter || "",
      difficulty: it.diff || "Medium",
      marks: Number(it.marks) || 1,
      question: stripHtml(it.question),
      answer_key: stripHtml(it.answer),
    }));
    try {
      const res = await createQuestionsBulk(payloads);
      const count = res?.total_created ?? payloads.length;
      await loadQuestions();
      toast.success(`${count} question${count > 1 ? "s" : ""} added`);
    } catch (err) {
      toast.error("Could not add questions");
    }
  };
  const generatePaper = (d) => {
    const target = Number(d.marks) || 50;
    let total = 0;
    const picked = [];
    for (const q of [...questions].sort(() => 0.5 - Math.random())) {
      if (total + q.marks <= target) {
        picked.push(q);
        total += q.marks;
      }
      if (total >= target) break;
    }
    toast.success(`Paper generated: ${picked.length} questions · ${total} marks`);
  };

  // ---- Marks Entry -> Publish single student's report to their portal ----
  const shareReportToStudent = async (m) => {
    const stu = students.find((s) => s.id === m.studentUuid);
    const matchedClass = classesData.find((c) => c.name === meClass);
    const matchedExam = exams.find((e) => e.name === meExam && e.class === meClass);

    if (!matchedClass || !matchedExam || !m.resultUuid || !m.studentUuid || !m.sectionUuid) {
      toast.error("Select a valid class, exam, and section before publishing");
      return;
    }

    try {
      setPublishingRow((p) => ({ ...p, [m.resultUuid]: true }));
      await publishExamMarks({
        examUuid: matchedExam?.id,
        classUuid: matchedClass?.id,
        sectionUuid: m.sectionUuid,
        resultUuids: [m.resultUuid],
        studentUuids: [m.studentUuid],
      });

      // Keep the legacy local portal view in sync only when its local student
      // record is available. The API publish above is the source of truth.
      if (stu) {
        const entry = {
          studentId: stu.id,
          studentName: stu.name,
          admissionNo: stu.admissionNo,
          marks: Object.fromEntries(m.subjects.map((s) => [s.name, s.marks])),
        };
        storedResultsApi.saveBatch(meClass, meSection, meExam, [entry]);
        storedResultsApi.publish(meClass, meSection, meExam);
      }

      setSharedStudents((p) => ({ ...p, [m.studentUuid]: true }));
      toast.success(`Report published to ${m.name}'s student portal`);
    } catch (err) {
      toast.error(`Could not publish report for ${m.name}`);
    } finally {
      setPublishingRow((p) => ({ ...p, [m.resultUuid]: false }));
    }
  };
    // ---- Marks Entry -> Import marks from Excel ----
  const handleMarksImportResult = (res) => {
    const saved = res?.saved ?? 0;
    const errors = res?.errors ?? 0;
    const warnings = res?.warnings ?? 0;
    const corrected = res?.corrected_calculation ?? 0;

    const extra = [
      corrected ? `${corrected} auto-corrected` : null,
      warnings ? `${warnings} warning(s)` : null,
      errors ? `${errors} error(s)` : null,
    ]
      .filter(Boolean)
      .join(", ");

    if (saved > 0) {
      toast.success(
        res?.message
          ? `${res.message}${extra ? ` (${extra})` : ""}`
          : `${saved} row(s) imported${extra ? ` — ${extra}` : ""}`,
      );
    } else {
      toast.error(extra || "No rows were imported");
    }

    if (res?.errors_detail?.length) {
      const first = res.errors_detail[0];
      toast.error(`Row ${first.row} (${first.admission_no}): ${first.errors?.[0]}`);
    }
  };

  // ---- Marks Entry -> Export the current class/section/exam marks as CSV ----
  const exportMarksCsv = () => {
    if (!examMarks.length) {
      toast.error("No marks to export");
      return;
    }
    const subjectNames = marksSubjectColumns.map((c) => c.name);
    const rows = [["Roll", "Name", ...subjectNames, "Total", "%", "Grade", "Status"]];
    examMarks.forEach((m) => {
      const subjMap = Object.fromEntries(m.subjects.map((s) => [s.uuid, s.marks]));
      rows.push([
        m.roll,
        m.name,
        ...marksSubjectColumns.map((c) => subjMap[c.uuid] ?? ""),
        m.total,
        m.percentage,
        m.gradeLabel ?? grade(m.percentage ?? 0).g,
        m.status ?? "",
      ]);
    });
    const blob = new Blob([rows.map((r) => r.join(",")).join("\n")], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `marks-${meClass}-${meSection}-${meExam}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("Marks exported");
  };

    const classOptions = classesData.length
    ? classesData.map((c) => c.name)
    : ["VI", "VII", "VIII", "IX", "X", "XI", "XII"];
  const subjectOptions = ["Math", "Science", "English", "Social", "Hindi", "CS", "Biology", "Economics"];
  const examTypeOptions = categories.map((c) => c.name);
  const examNameOptions = Array.from(new Set(exams.map((e) => e.name))).filter(Boolean);

  const filteredQ = questions.filter((q) => {
    if (search && !(q.subject + q.chapter + q.id + q.question).toLowerCase().includes(search.toLowerCase())) return false;
    if (qfClass !== "all" && q.className !== qfClass) return false;
    if (qfSubject !== "all" && q.subject !== qfSubject) return false;
    if (qfExam !== "all" && q.examType !== qfExam) return false;
    return true;
  });

  // ---- Pagination — same usePagination + PaginationBar/RowsPerPageSelect
  // pattern as the Timetable Engine page, applied to every data table here.
  const categoriesPage = usePagination(categories, 10);
  const examsPage = usePagination(exams, 10);
  const papersPage = usePagination(papers, 10);
  const questionsPage = usePagination(filteredQ, 10);
  const marksPage = usePagination(examMarks, 10);

  const dashStudents = useMemo(
    () => students.filter((s) => s.class === dashClass && s.section === dashSection),
    [students, dashClass, dashSection],
  );
  const dashRows = useMemo(() => buildDashRows(dashStudents), [dashStudents]);
  const dashAvg = dashRows.length ? Math.round((dashRows.reduce((a, r) => a + r.percent, 0) / dashRows.length) * 10) / 10 : 0;
  const dashPass = dashRows.filter((r) => r.percent >= 33).length;
  const dashTopper = dashRows.find((r) => r.rank === 1);

  return (
    <PageContainer>
      <PageHeader
        eyebrow="Academic"
        title="Examination Engine"
        actions={
          <>
            {/* <Button
              size="sm"
              className="gradient-primary border-0"
              onClick={() => {
                setExamEdit(null);
                setExamOpen(true);
              }}
            >
              <Plus className="h-4 w-4" />
              New Exam
            </Button> */}
          </>
        }
      />

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <KpiCard
          label="Upcoming Exams"
          value={exams.filter((e) => e.status !== "Completed").length.toString()}
          icon={<BookOpen className="h-5 w-5" />}
          tone="primary"
        />
        <KpiCard
          label="Marks Entered"
          value="86%"
          delta={4.2}
          icon={<FileText className="h-5 w-5" />}
          tone="info"
        />
        <KpiCard
          label="Average Score"
          value="78.4"
          delta={1.8}
          icon={<Trophy className="h-5 w-5" />}
          tone="success"
        />
        <KpiCard
          label="Questions Bank"
          value={questions.length.toString()}
          icon={<AlertTriangle className="h-5 w-5" />}
          tone="warning"
        />
      </div>

      <Tabs value={tab} onValueChange={handleTabChange}>
        <TabsList className="flex-wrap h-auto">
          {/* <TabsTrigger value="dash">Dashboard</TabsTrigger> */}
          <TabsTrigger value="categories">Categories</TabsTrigger>
          <TabsTrigger value="schedule">Schedule</TabsTrigger>
          <TabsTrigger value="papers">Subjects & Papers</TabsTrigger>
          <TabsTrigger value="qb">Question Bank</TabsTrigger>
          {/* <TabsTrigger value="blueprints">Blueprints</TabsTrigger> */}
          {/* <TabsTrigger value="templates">Templates</TabsTrigger> */}
          {/* <TabsTrigger value="solutions">Solutions</TabsTrigger> */}
          <TabsTrigger value="marks">Marks Entry</TabsTrigger>
          <TabsTrigger value="results">Top Performers</TabsTrigger>
        </TabsList>

        <TabsContent value="dash" className="mt-4 space-y-4">
          <Card className="border-border/60">
            <CardHeader className="pb-3">
              <CardTitle className="text-base">Class Performance Explorer</CardTitle>
              <CardDescription>Pick a class &amp; section, apply the filter, then click any student to drill into their subject-wise breakdown.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex flex-wrap items-end gap-3">
                <div className="space-y-1">
                  <Label className="text-xs">Class</Label>
                  <Select value={dashClass} onValueChange={setDashClass}>
                    <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
                    <SelectContent>{classOptions.map((c) => <SelectItem key={c} value={c}>Class {c}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
                <div className="space-y-1">
                  <Label className="text-xs">Section</Label>
                  <Select value={dashSection} onValueChange={setDashSection}>
  <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
  <SelectContent>
    {sectionsForClass(dashClass).map((s) => (
      <SelectItem key={s} value={s}>Section {s}</SelectItem>
    ))}
  </SelectContent>
</Select>
                </div>
                <Button size="sm" className="gradient-primary border-0" onClick={() => setDashApplied(true)}>
                  Apply Filters
                </Button>
                {dashApplied && (
                  <Button size="sm" variant="ghost" onClick={() => setDashApplied(false)}>Clear</Button>
                )}
              </div>

              {!dashApplied ? (
                <div className="rounded-lg border border-dashed border-border/60 p-10 text-center text-sm text-muted-foreground">
                  Select a class &amp; section and press <span className="font-medium text-foreground">Apply Filters</span> to view results.
                </div>
              ) : dashRows.length === 0 ? (
                <div className="rounded-lg border border-dashed border-border/60 p-10 text-center text-sm text-muted-foreground">
                  No students found for Class {dashClass} · Section {dashSection}.
                </div>
              ) : (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    <KpiCard label="Students" value={dashRows.length.toString()} icon={<BookOpen className="h-5 w-5" />} tone="primary" />
                    <KpiCard label="Class Average" value={dashAvg + "%"} icon={<Trophy className="h-5 w-5" />} tone="info" />
                    <KpiCard label="Passed" value={`${dashPass}/${dashRows.length}`} icon={<FileCheck2 className="h-5 w-5" />} tone="success" />
                    <KpiCard label="Topper" value={dashTopper ? `${dashTopper.percent}%` : "—"} icon={<Trophy className="h-5 w-5" />} tone="warning" />
                  </div>
                  <div className="rounded-lg border border-border/60 overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Roll</TableHead>
                          <TableHead>Student</TableHead>
                          <TableHead className="text-right">Total</TableHead>
                          <TableHead className="text-right">%</TableHead>
                          <TableHead>Grade</TableHead>
                          <TableHead className="text-right">Rank</TableHead>
                          <TableHead className="w-10"></TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {dashRows.map((r) => (
                          <TableRow key={r.id} className="cursor-pointer" onClick={() => setDashDetail(r)}>
                            <TableCell className="font-mono text-xs">{r.roll}</TableCell>
                            <TableCell className="font-medium text-sm">{r.name}</TableCell>
                            <TableCell className="text-right text-sm">{r.total}/{r.maxTotal}</TableCell>
                            <TableCell className="text-right text-sm">{r.percent}%</TableCell>
                            <TableCell><Badge variant="outline" className={grade(r.percent).c}>{grade(r.percent).g}</Badge></TableCell>
                            <TableCell className="text-right text-sm">#{r.rank}</TableCell>
                            <TableCell><Eye className="h-4 w-4 text-muted-foreground" /></TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </>
              )}
            </CardContent>
          </Card>

          <div className="grid lg:grid-cols-3 gap-4">
            <Card className="lg:col-span-2 border-border/60">
              <CardHeader>
                <CardTitle className="text-base">Subject-wise Average vs Top</CardTitle>
                <CardDescription>Term 1 · Class X</CardDescription>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={examPerformance}>
                    <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
                    <XAxis dataKey="subject" fontSize={11} />
                    <YAxis fontSize={11} />
                    <Tooltip
                      contentStyle={{
                        background: "var(--popover)",
                        border: "1px solid var(--border)",
                        borderRadius: 8,
                        fontSize: 12,
                      }}
                    />
                    <Bar dataKey="avg" fill="var(--chart-1)" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="top" fill="var(--chart-2)" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
            <Card className="border-border/60">
              <CardHeader>
                <CardTitle className="text-base">Competency Radar</CardTitle>
                <CardDescription>CBSE skill mapping</CardDescription>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={280}>
                  <RadarChart
                    data={[
                      { skill: "Reasoning", v: 78 },
                      { skill: "Application", v: 82 },
                      { skill: "Recall", v: 88 },
                      { skill: "Analysis", v: 72 },
                      { skill: "Creativity", v: 65 },
                      { skill: "Communication", v: 80 },
                    ]}
                  >
                    <PolarGrid stroke="var(--border)" />
                    <PolarAngleAxis dataKey="skill" fontSize={10} />
                    <PolarRadiusAxis fontSize={10} />
                    <Radar
                      dataKey="v"
                      stroke="var(--chart-2)"
                      fill="var(--chart-2)"
                      fillOpacity={0.4}
                    />
                  </RadarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="categories" className="mt-4">
          <Card className="border-border/60">
            <CardHeader className="flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle className="text-base">Exam Categories</CardTitle>
              </div>
              <div className="flex items-center gap-3">
                <RowsPerPageSelect {...categoriesPage} />
                <Button
                  size="sm"
                  className="gradient-primary border-0"
                  onClick={() => {
                    setCatEdit(null);
                    setCatOpen(true);
                  }}
                >
                  <Plus className="h-4 w-4" /> New Category
                </Button>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Description</TableHead>
                    <TableHead className="w-10"></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {categoriesPage.pageItems.map((c) => (
                    <TableRow key={c.id}>
                      <TableCell className="font-medium">{c.name}</TableCell>
                      <TableCell className="text-muted-foreground">{c.description}</TableCell>
                      {/* <TableCell>{c.weight}%</TableCell> */}
                      <TableCell>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-7 w-7">
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            {/* <DropdownMenuItem onClick={() => toast.info(`${c.name} · ${c.description}`)}>
                              <Eye className="h-4 w-4" />
                              View
                            </DropdownMenuItem> */}
                            <DropdownMenuItem
                              onClick={() => {
                                setCatEdit(c);
                                setCatOpen(true);
                              }}
                            >
                              <Pencil className="h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-destructive focus:text-destructive"
                             onClick={async () => {
  try {
    await deleteExamCategory(c.id);
    setCategories((p) => p.filter((x) => x.id !== c.id));
    toast.success("Category removed");
  } catch (err) {
    toast.error("Could not delete category");
  }
}}
                            >
                              <Trash2 className="h-4 w-4" />
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
{categoriesLoading && (
  <TableRow>
    <TableCell colSpan={3} className="text-center text-sm text-muted-foreground py-8">
      Loading categories…
    </TableCell>
  </TableRow>
)}
{!categoriesLoading && !categoriesPage.pageItems.length && (
  <TableRow>
    <TableCell colSpan={3} className="text-center text-sm text-muted-foreground py-8">
      No categories yet.
    </TableCell>
  </TableRow>
)}
                </TableBody>
              </Table>
              <PaginationBar {...categoriesPage} itemLabel="categories" showPageSize={false} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="schedule" className="mt-4">
          <Card className="border-border/60">
            <CardHeader className="flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle className="text-base">Exam Schedule</CardTitle>
              </div>
              <div className="flex items-center gap-3">
                <RowsPerPageSelect {...examsPage} />
                <Button
                  size="sm"
                  className="gradient-primary border-0"
                  onClick={() => {
                    setExamEdit(null);
                    setExamOpen(true);
                  }}
                >
                  <Plus className="h-4 w-4" /> New Exam
                </Button>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Exam</TableHead>
                    <TableHead>Class</TableHead>
                    <TableHead>From</TableHead>
                    <TableHead>To</TableHead>
                    <TableHead>Subjects</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="w-10"></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {examsPage.pageItems.map((u) => (
                    <TableRow
                      key={u.id}
                      className="cursor-pointer hover:bg-muted/40"
                      onClick={(e) => {
                        if (e.target.closest("[data-no-row]")) return;
                        navigate(`/exams/${u.id}`);
                      }}
                    >
                      <TableCell className="font-medium">{u.name}</TableCell>
                      <TableCell>{u.class}</TableCell>
                      <TableCell>{u.from}</TableCell>
                      <TableCell>{u.to}</TableCell>
                      <TableCell>{u.subjects}</TableCell>
                      <TableCell>
                        <Badge
                          variant={
                            u.status === "In Progress"
                              ? "default"
                              : u.status === "Draft"
                                ? "outline"
                                : "secondary"
                          }
                        >
                          {u.status}
                        </Badge>
                      </TableCell>
                      <TableCell data-no-row>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-7 w-7">
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
  <DropdownMenuItem
    onClick={(e) => {
      e.stopPropagation();
      toast.info(`${u.name} · ${u.class} · ${u.from} – ${u.to}`);
    }}
  >
    <Eye className="h-4 w-4" />
    View
  </DropdownMenuItem>
  <DropdownMenuItem
    onClick={(e) => {
      e.stopPropagation();
      setExamEdit(u);
      setExamOpen(true);
    }}
  >
    <Pencil className="h-4 w-4" />
    Edit
  </DropdownMenuItem>
  <DropdownMenuSeparator />
   <DropdownMenuItem
    className="text-destructive focus:text-destructive"
    onClick={async (e) => {
      e.stopPropagation();
      try {
        await deleteExam(u.id);
        setExams((p) => p.filter((x) => x.id !== u.id));
        toast.success("Exam deleted");
      } catch (err) {
        toast.error("Could not delete exam");
      }
    }}
  >
    <Trash2 className="h-4 w-4" />
    Delete
  </DropdownMenuItem>
</DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                                   {examsLoading && (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center text-sm text-muted-foreground py-8">
                        Loading exams…
                      </TableCell>
                    </TableRow>
                  )}
                  {!examsLoading && !examsPage.pageItems.length && (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center text-sm text-muted-foreground py-8">
                        No exams scheduled yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
              <PaginationBar {...examsPage} itemLabel="exams" showPageSize={false} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="papers" className="mt-4">
          <Card className="border-border/60">
            <CardHeader className="flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle className="text-base">Subjects & Papers</CardTitle>
              </div>
              <div className="flex gap-2 items-center">
                <RowsPerPageSelect {...papersPage} />
                <Button size="sm" variant="outline" onClick={downloadPapersTemplate}>
                  <Download className="h-4 w-4" />
                  Template
                </Button>
                                <input
                  ref={papersImportRef}
                  type="file"
                  accept=".xlsx,.xls,.csv"
                  hidden
                  onChange={async (e) => {
                    const file = e.target.files?.[0];
                    e.target.value = "";
                    if (!file) return;
                    try {
                      setPapersImporting(true);
                      const res = await importExamPapers(file);
                      await loadPapers();
                      toast.success(
                        res?.message ||
                          `${res?.created_papers ?? 0} paper(s) imported`,
                      );
                    } catch (err) {
                      toast.error("Could not import papers");
                    } finally {
                      setPapersImporting(false);
                    }
                  }}
                />
                <Button
                  size="sm"
                  variant="outline"
                  disabled={papersImporting}
                  onClick={() => papersImportRef.current?.click()}
                >
                  <Upload className="h-4 w-4" />
                  {papersImporting ? "Importing…" : "Import Papers"}
                </Button>
                <Button
                  size="sm"
                  className="gradient-primary border-0"
                  onClick={() => {
                    setPaperEdit(null);
                    setMultiPaperOpen(true);
                  }}
                >
                  <Plus className="h-4 w-4" /> Add Subject / Paper
                </Button>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Category</TableHead>
                    <TableHead>Class</TableHead>
                    <TableHead>Subject</TableHead>
                    <TableHead>Paper</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead>Time</TableHead>
                    <TableHead>Duration</TableHead>
                    <TableHead>Max</TableHead>
                    <TableHead>Room</TableHead>
                    <TableHead className="w-10"></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {papersPage.pageItems.map((p) => (
                    <TableRow key={p.id}>
                      <TableCell><Badge variant="secondary">{p.category}</Badge></TableCell>
                      <TableCell>{p.className}</TableCell>
                      <TableCell className="font-medium">{p.subject}</TableCell>
                      <TableCell>{p.paper}</TableCell>
                      <TableCell>{p.date}</TableCell>
                      <TableCell>{p.time}</TableCell>
                      <TableCell>{p.duration}m</TableCell>
                      <TableCell>{p.maxMarks}</TableCell>
                      <TableCell>{p.room}</TableCell>
                      <TableCell>
                        <DropdownMenu>
