      } catch (err) {
        anyFailed = true;
      }
    }

    if (createdCount) {
      await loadPapers(); 
      toast.success(`${createdCount} paper(s) added`);
    }
    if (anyFailed) {
      toast.error("Some papers could not be created");
    }
