          <AttendanceTab attendance={s.attendance_percentage || 0} seed={seed} />
        </TabsContent>

        {/* ══════════════════════ ASSIGNMENTS TAB ══════════════════════ */}
        <TabsContent value="assignments" className="mt-4">
          <AssignmentsTab klass={`${s.class_name || "-"}-${s.section_name || "-"}`} seed={seed} />
