  const years = Array.from({ length: 8 }, (_, i) => {
    const y = startYear + i;
    return `${y}-${String(y + 1).slice(-2)}`;
  });
  if (academicYear && !years.includes(academicYear)) years.push(academicYear);
  return years.sort();
