          size="sm"
          onClick={clearTimetableFilters}
          disabled={!selectedClassUUID && !selectedSectionUUID}
        >
          Clear filters
        </Button>
        </div>
      </div> */}

      <div className="hidden grid-cols-2 gap-4 md:grid-cols-4 mb-6">
