/* AUDIT REPORT — REAL PERIOD FILTERING                              */
/* ================================================================== */

function getAuditDateRange(period) {
  const now = new Date();

  // Remove time for reliable date comparison
  const today = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()
  );

  let from;
  let to = today;

  if (period === "week") {
    // Monday -> today
    const day = today.getDay(); // 0 = Sunday
    const diff = day === 0 ? 6 : day - 1;

    from = new Date(today);
    from.setDate(today.getDate() - diff);
  }

  if (period === "month") {
    // 1st of current month -> today
    from = new Date(
      today.getFullYear(),
      today.getMonth(),
      1
    );
  }

  if (period === "year") {
    // Academic year: April -> March
    const currentYear = today.getFullYear();
    const currentMonth = today.getMonth() + 1;

    const academicStartYear =
      currentMonth >= 4
        ? currentYear
        : currentYear - 1;

    from = new Date(
      academicStartYear,
      3, // April
      1
    );
  }

  return { from, to };
}


function normalizePaymentForAudit(txn, students = []) {
  const student = students.find(
    (s) => s.student_uuid === txn.student_uuid
  );

  const status =
    String(txn.transaction_status || "").toUpperCase() === "SUCCESS"
      ? "Success"
      : txn.transaction_status || "Pending";

  return {
    id:
      txn.receipt_no ||
      txn.transaction_uuid ||
      `TXN-${Math.random().toString(36).slice(2)}`,

    transaction_uuid: txn.transaction_uuid,

    student_uuid: txn.student_uuid,

    student_name:
      txn.student_name ||
      student?.full_name ||
      "—",

    class_name:
      student?.class_name ||
      txn.class_name ||
      "—",

    section:
      student?.section_name ||
      txn.section_name ||
      "—",

    amount: Number(
      txn.total_amount ??
      txn.paid_amount ??
      txn.amount ??
      0
    ),

    discount: Number(
      txn.discount_amount ?? 0
    ),

    lateFee: Number(
      txn.late_fee ?? 0
    ),

    mode:
      txn.payment_mode ||
      "—",

    status,

    date: txn.created_at
      ? new Date(txn.created_at)
          .toISOString()
          .split("T")[0]
      : "",

    created_at: txn.created_at,

    receipt_no: txn.receipt_no,

    payment_type:
      txn.payment_type ||
      "PAYMENT",
  };
}


function isDateInsideRange(dateValue, from, to) {
  if (!dateValue) return false;

  const date = new Date(dateValue);

  if (Number.isNaN(date.getTime())) {
    return false;
  }

  const normalized = new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate()
  );

  return normalized >= from && normalized <= to;
}


async function openAuditReport({
  period,
  kpis,
  students = [],
}) {
  try {
    const { from, to } =
      getAuditDateRange(period);

    /*
     * IMPORTANT:
     * Fetch actual payments here instead of using the page-level
     * `ledger`, because the page ledger can be empty.
     */
    const response = await getPayments({
      limit: 500,
    });

    const payments =
      response?.data?.data ??
      response?.data ??
      [];

    const auditPayments = payments
      .map((txn) =>
        normalizePaymentForAudit(
          txn,
          students
        )
      )
      .filter((txn) =>
        isDateInsideRange(
          txn.created_at,
          from,
          to
        )
      );

    /*
     * Collection must only count successful payments.
     */
    const successfulPayments =
      auditPayments.filter(
        (txn) =>
          txn.status === "Success"
      );

    const periodCollection =
      successfulPayments.reduce(
        (sum, txn) =>
          sum + Number(txn.amount || 0),
        0
      );

    const periodDiscount =
      successfulPayments.reduce(
        (sum, txn) =>
          sum + Number(txn.discount || 0),
        0
      );

    const periodLateFee =
      successfulPayments.reduce(
        (sum, txn) =>
          sum + Number(txn.lateFee || 0),
        0
      );

    /*
     * Keep current outstanding/future position from the dashboard.
     * These are current financial-position values rather than
     * historical payment-period values.
     */
    const auditKpis = {
      collection: periodCollection,

      totalDue:
        Number(kpis?.totalDue || 0),

      overdueStudents:
        Number(kpis?.overdueStudents || 0),

      future:
        Number(kpis?.future || 0),

      discountTotal:
        periodDiscount,

      lateCollected:
        periodLateFee,
    };

    const label =
      period === "week"
        ? "Weekly"
        : period === "month"
        ? "Monthly"
        : "Annual";

    const fromLabel =
      from.toLocaleDateString(
        "en-IN",
        {
          day: "2-digit",
          month: "short",
          year: "numeric",
        }
      );

    const toLabel =
      to.toLocaleDateString(
        "en-IN",
        {
          day: "2-digit",
          month: "short",
          year: "numeric",
        }
      );

    const today =
      new Date().toLocaleDateString(
        "en-IN",
        {
          day: "2-digit",
          month: "long",
          year: "numeric",
        }
      );

    const win =
      window.open("", "_blank");

    if (!win) {
      toast.error(
        "Please allow pop-ups to view the report"
      );
      return;
    }

    /*
     * Sort newest first.
     */
    const sortedLedger =
      [...auditPayments].sort(
        (a, b) =>
          new Date(b.created_at || 0) -
          new Date(a.created_at || 0)
      );

    win.document.write(`
      <html>
        <head>
          <title>
            Fees & Finance Audit Report — ${label}
          </title>

          <style>
            * {
              box-sizing: border-box;
            }

            body {
              font-family:
                -apple-system,
                BlinkMacSystemFont,
                "Segoe UI",
                sans-serif;

              padding: 40px;
              color: #111827;
              background: #ffffff;
            }

            h1 {
              font-size: 22px;
              margin: 0 0 6px;
              color: #0f172a;
            }

            h2 {
              font-size: 15px;
              margin-top: 30px;
              margin-bottom: 0;
              border-bottom: 1px solid #d1d5db;
              padding-bottom: 8px;
              color: #111827;
            }

            .muted {
              color: #64748b;
              font-size: 13px;
            }

            .period {
              margin-top: 8px;
              padding: 8px 12px;
              background: #f8fafc;
              border: 1px solid #e2e8f0;
              border-radius: 6px;
              font-size: 13px;
            }

            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 10px;
              font-size: 13px;
            }

            td,
            th {
              text-align: left;
              padding: 9px 10px;
              border-bottom: 1px solid #e5e7eb;
            }

            th {
              font-weight: 600;
              color: #111827;
              background: #f8fafc;
            }

            .right {
              text-align: right;
            }

            .center {
