            }

            .success {
              color: #15803d;
              font-weight: 600;
            }

            .pending {
              color: #b45309;
              font-weight: 600;
            }

            .empty {
              text-align: center;
              padding: 30px;
              color: #64748b;
            }

            .footer {
              margin-top: 35px;
              font-size: 11px;
