];
const STATUS_OPTIONS = ["Active", "Maintenance", "Under Construction"];
const ROOM_TYPES = [
  "Classroom",
  "Lab",
  "Staff",
  "Hall",
  "Library",
  "Office",
  "Hostel",
  "Storage",
];
const FACILITIES_LIST = [
  "AC",
