              <CardDescription>
                Components tracked in this report
              </CardDescription>

            </CardHeader>

            <CardContent>

              <div className="flex flex-wrap gap-2">

                {components.map(
                  (component) => (
                    <Badge
                      key={
                        component
                      }
                      variant="secondary"
                      className="text-xs"
                    >
                      {
                        component
                      }
                    </Badge>
                  )
                )}

              </div>

            </CardContent>

          </Card>
        )}

    </div>
  );
