import { useEffect, useMemo, useState } from "react";
import {
  CheckCircle2,
  ClipboardList,
  Download,
  FileText,
  Loader2,
  MessageSquare,
  Paperclip,
  Upload,
} from "lucide-react";
import { toast } from "sonner";
import studentModel from "../../api/studentModel";
import { PageContainer, PageHeader } from "../../components/page-shell";
import { Badge } from "../../components/ui/badge";
import { Button } from "../../components/ui/button";
import { Card, CardContent } from "../../components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import { Input } from "../../components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";
import { Textarea } from "../../components/ui/textarea";

const getError = (error) =>
  error?.response?.data?.detail?.message ||
  error?.response?.data?.detail ||
  error?.message ||
  "Request failed.";

const STATUS_META = {
  PENDING: { accent: "bg-warning", ring: "ring-warning/20", label: "Pending" },
  SUBMITTED: { accent: "bg-primary", ring: "ring-primary/20", label: "Submitted" },
  LATE: { accent: "bg-destructive", ring: "ring-destructive/20", label: "Late" },
  RESUBMITTED: { accent: "bg-primary", ring: "ring-primary/20", label: "Resubmitted" },
  GRADED: { accent: "bg-success", ring: "ring-success/20", label: "Graded" },
};

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(dateStr);
  return Math.round((due - today) / (1000 * 60 * 60 * 24));
}

function DueChip({ dateStr, isOverdue }) {
  if (!dateStr) return null;
  const diff = daysUntil(dateStr);
  let text = `Due ${dateStr}`;
  let tone = "text-muted-foreground bg-muted";
  if (isOverdue) {
    text = diff === 0 ? "Due today" : `${Math.abs(diff)}d overdue`;
    tone = "text-destructive bg-destructive/10";
  } else if (diff === 0) {
    text = "Due today";
    tone = "text-warning bg-warning/10";
  } else if (diff === 1) {
    text = "Due tomorrow";
    tone = "text-warning bg-warning/10";
  } else if (diff > 1 && diff <= 3) {
    text = `Due in ${diff}d`;
    tone = "text-warning bg-warning/10";
  }
  return <span className={`text-[11px] font-medium px-2 py-0.5 rounded-full ${tone}`}>{text}</span>;
}

function Initials({ name }) {
  const value = (name || "?")
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
  return (
    <div className="h-9 w-9 shrink-0 rounded-full bg-primary/10 text-primary text-xs font-semibold flex items-center justify-center">
      {value || "?"}
    </div>
  );
}

export default function Assignments() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(null);
  const [detail, setDetail] = useState(null);
  const [inquiries, setInquiries] = useState([]);
  const [file, setFile] = useState(null);
  const [comment, setComment] = useState("");
  const [question, setQuestion] = useState("");
  const [saving, setSaving] = useState(false);

  const loadAssignments = async () => {
    setLoading(true);
    try {
      setRows((await studentModel.getMyAssignments())?.data || []);
    } catch (error) {
      toast.error(getError(error));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAssignments();
  }, []);

  const groups = useMemo(
    () => ({
      pending: rows.filter((row) => row.submission_status === "PENDING"),
      submitted: rows.filter((row) => ["SUBMITTED", "LATE", "RESUBMITTED"].includes(row.submission_status)),
      graded: rows.filter((row) => row.submission_status === "GRADED"),
    }),
    [rows],
  );

  const overdue = groups.pending.filter(
    (row) => row.due_date && row.due_date < new Date().toISOString().slice(0, 10),
  );

  const completed = groups.submitted.length + groups.graded.length;
  const completionPct = rows.length ? Math.round((completed / rows.length) * 100) : 0;

  const openAssignment = async (assignment) => {
    setOpen(assignment);
    setDetail(null);
    setFile(null);
    setComment("");
    setQuestion("");
    try {
      const [assignmentResult, inquiryResult] = await Promise.all([
        studentModel.getMyAssignmentDetail(assignment.assignment_uuid),
        studentModel.getAssignmentInquiries(assignment.assignment_uuid),
      ]);
      setDetail(assignmentResult?.data || null);
      setInquiries(inquiryResult?.data || []);
    } catch (error) {
      toast.error(getError(error));
    }
  };

  const submitAssignment = async () => {
    if (!file) return toast.error("Choose an answer PDF.");
    if (file.type !== "application/pdf") return toast.error("Only PDF files are allowed.");
    setSaving(true);
    try {
      await studentModel.submitAssignment(open.assignment_uuid, { file, comment });
      toast.success("Assignment submitted successfully.");
      await loadAssignments();
      await openAssignment(open);
    } catch (error) {
      toast.error(getError(error));
    } finally {
      setSaving(false);
    }
  };

  const sendInquiry = async () => {
    if (!question.trim()) return toast.error("Enter your question.");
    setSaving(true);
    try {
      await studentModel.createAssignmentInquiry(open.assignment_uuid, question);
      setInquiries((await studentModel.getAssignmentInquiries(open.assignment_uuid))?.data || []);
      setQuestion("");
      toast.success("Inquiry sent.");
    } catch (error) {
      toast.error(getError(error));
    } finally {
      setSaving(false);
    }
  };

  return (
    <PageContainer>
      <PageHeader
        eyebrow="Student Portal"
        title="My Assignments"
        description={`${rows.length} assignments assigned to you.`}
      />

      {/* Overview strip */}
      <Card className="mb-5 border-border/60">
        <CardContent className="p-5">
          <div className="flex flex-col sm:flex-row sm:items-center gap-5 sm:gap-8">
            <div className="flex items-center gap-8 flex-1">
              <div>
                <div className="text-2xl font-semibold tabular-nums">{groups.pending.length}</div>
                <div className="text-xs text-muted-foreground mt-0.5">Pending</div>
              </div>
              <div className="h-8 w-px bg-border" />
              <div>
                <div className="text-2xl font-semibold tabular-nums text-destructive">{overdue.length}</div>
                <div className="text-xs text-muted-foreground mt-0.5">Overdue</div>
              </div>
              <div className="h-8 w-px bg-border" />
              <div>
                <div className="text-2xl font-semibold tabular-nums text-success">{completed}</div>
                <div className="text-xs text-muted-foreground mt-0.5">Completed</div>
              </div>
            </div>
            <div className="flex-1 sm:max-w-xs">
              <div className="flex items-center justify-between text-xs text-muted-foreground mb-1.5">
                <span>Overall progress</span>
                <span className="font-medium text-foreground">{completionPct}%</span>
              </div>
              <div className="h-1.5 rounded-full bg-muted overflow-hidden">
                <div
                  className="h-full rounded-full bg-success transition-[width] duration-500"
                  style={{ width: `${completionPct}%` }}
                />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {loading ? (
        <div className="py-20 flex justify-center">
          <Loader2 className="animate-spin text-muted-foreground" />
        </div>
      ) : (
        <Tabs defaultValue="pending">
          <TabsList>
            <TabsTrigger value="pending">Pending ({groups.pending.length})</TabsTrigger>
            <TabsTrigger value="submitted">Submitted ({groups.submitted.length})</TabsTrigger>
            <TabsTrigger value="graded">Graded ({groups.graded.length})</TabsTrigger>
          </TabsList>

          {Object.entries(groups).map(([key, assignments]) => (
            <TabsContent key={key} value={key} className="mt-4">
              {!assignments.length ? (
                <div className="text-center py-16 border border-dashed rounded-xl">
                  <ClipboardList className="h-8 w-8 mx-auto text-muted-foreground/50 mb-3" />
                  <p className="text-sm text-muted-foreground">
                    {key === "pending"
                      ? "Nothing pending. You're caught up."
                      : key === "submitted"
                      ? "Nothing waiting on a grade right now."
                      : "No graded assignments yet."}
                  </p>
                </div>
              ) : (
                <div className="space-y-2.5">
                  {assignments.map((assignment) => {
                    const isOverdue =
                      assignment.submission_status === "PENDING" &&
                      assignment.due_date &&
                      assignment.due_date < new Date().toISOString().slice(0, 10);
                    const meta = STATUS_META[isOverdue ? "LATE" : assignment.submission_status] || STATUS_META.PENDING;

                    return (
                      <Card
                        key={assignment.assignment_uuid}
                        className="relative overflow-hidden border-border/60 hover:border-border transition-colors"
                      >
                        <div className={`absolute left-0 top-0 bottom-0 w-1 ${meta.accent}`} />
                        <CardContent className="p-4 pl-5">
                          <div className="flex items-start gap-3">
                            <Initials name={assignment.teacher_name} />
                            <div className="flex-1 min-w-0">
                              <div className="flex items-start justify-between gap-3">
                                <div className="min-w-0">
                                  <div className="font-medium text-sm leading-snug truncate">{assignment.title}</div>
                                  <div className="text-xs text-muted-foreground mt-0.5">
                                    {assignment.teacher_name || "Unassigned teacher"}
                                  </div>
                                </div>
                                <Button
                                  size="sm"
                                  variant={assignment.submission_status === "PENDING" ? "default" : "outline"}
                                  onClick={() => openAssignment(assignment)}
                                  className="shrink-0"
                                >
                                  {assignment.submission_status === "PENDING" && <Upload className="h-3.5 w-3.5" />}
                                  Open
                                </Button>
                              </div>

                              <div className="flex flex-wrap items-center gap-1.5 mt-2.5">
                                <Badge variant="outline" className="text-[11px] font-normal">
                                  {assignment.subject_name}
                                </Badge>
                                <DueChip dateStr={assignment.due_date} isOverdue={isOverdue} />
                                {assignment.submission_status === "GRADED" && (
                                  <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full bg-success/10 text-success">
                                    {assignment.obtained_marks}/{assignment.max_marks} marks
                                  </span>
                                )}
                              </div>

                              {assignment.feedback && (
                                <div className="text-[12px] mt-3 p-2.5 bg-muted/40 rounded-lg flex gap-1.5 text-muted-foreground">
                                  <MessageSquare className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                                  <span>{assignment.feedback}</span>
                                </div>
                              )}
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    );
                  })}
                </div>
              )}
            </TabsContent>
          ))}
        </Tabs>
      )}

      <Dialog open={!!open} onOpenChange={(value) => !value && setOpen(null)}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{open?.title}</DialogTitle>
            <DialogDescription>
              {open?.subject_name} · Max {open?.max_marks} marks · Due {open?.due_date}
            </DialogDescription>
          </DialogHeader>

          {!detail ? (
            <Loader2 className="animate-spin mx-auto my-8" />
          ) : (
            <div className="space-y-6">
              {detail.my_submission?.status !== "GRADED" && (
                <>
                  <section>
                    <div className="text-sm font-medium mb-1.5">Instructions</div>
                    <p className="text-sm text-muted-foreground whitespace-pre-wrap leading-relaxed">
                      {detail.instructions || "No instructions provided."}
                    </p>
                  </section>

                  {!!detail.attachments?.length && (
                    <section>
                      <div className="text-sm font-medium mb-2">Attachments</div>
                      <div className="grid gap-2">
                        {detail.attachments.map((item) => (
                          <a
                            key={item.attachment_uuid}
                            href={item.file_url || item.resource_url}
                            target="_blank"
                            rel="noreferrer"
                            className="flex items-center gap-2.5 rounded-lg border border-border/60 px-3 py-2 text-sm hover:bg-muted/40 transition-colors"
                          >
                            <FileText className="h-4 w-4 text-muted-foreground shrink-0" />
                            <span className="flex-1 truncate">{item.original_file_name || item.attachment_type}</span>
                            <Download className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                          </a>
                        ))}
                      </div>
                    </section>
                  )}

                  {detail.my_submission?.status === "PENDING" && (
                    <section className="space-y-3 rounded-xl border border-dashed p-4">
                      <div className="flex items-center gap-2">
                        <Paperclip className="h-4 w-4 text-muted-foreground" />
                        <div className="text-sm font-medium">Upload your answer</div>
                      </div>
                      <Input
                        type="file"
                        accept="application/pdf,.pdf"
                        onChange={(event) => setFile(event.target.files?.[0] || null)}
                      />
                      <Textarea
                        value={comment}
                        onChange={(event) => setComment(event.target.value)}
                        placeholder="Add a note for your teacher (optional)"
                      />
                      <Button onClick={submitAssignment} disabled={saving} className="w-full sm:w-auto">
                        {saving ? <Loader2 className="animate-spin" /> : <Upload className="h-4 w-4" />}
                        Submit assignment
                      </Button>
                    </section>
                  )}
                </>
              )}

              {detail.my_submission?.status === "GRADED" && (
                <section className="space-y-3">
                  <div className="text-sm font-medium flex items-center gap-1.5">
                    <MessageSquare className="h-4 w-4" />
                    Ask a question
                  </div>
                  <Textarea
                    value={question}
                    onChange={(event) => setQuestion(event.target.value)}
                    placeholder="Ask your teacher about this assignment"
                  />
                  <Button variant="outline" onClick={sendInquiry} disabled={saving}>
                    Send
                  </Button>
                  {inquiries.length > 0 && (
                    <div className="space-y-2 pt-1">
                      {inquiries.map((item) => (
                        <div key={item.inquiry_uuid} className="rounded-lg bg-muted/40 p-3 text-sm space-y-1.5">
                          <div>
                            <span className="font-medium">You </span>
                            <span className="text-muted-foreground">{item.question}</span>
                          </div>
                          <div>
                            <span className="font-medium">Teacher </span>
                            <span className="text-muted-foreground">
                              {item.reply || "Waiting for a reply"}
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </section>
              )}
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(null)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

import { useEffect, useMemo, useState } from "react";
import { AlertTriangle, CalendarCheck, Loader2 } from "lucide-react";
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";
import studentModel from "../../api/studentModel";
import { KpiCard } from "../../components/kpi-card";
import { PageContainer, PageHeader } from "../../components/page-shell";
import { Badge } from "../../components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "../../components/ui/card";

const colors = { P: "bg-success/20 text-success border-success/30", A: "bg-destructive/20 text-destructive border-destructive/30", L: "bg-warning/20 text-warning border-warning/30", H: "bg-muted/40 text-muted-foreground", F: "border-dashed text-muted-foreground/40" };
const message = (error) => error?.response?.data?.detail?.message || error?.response?.data?.detail || error?.message || "Unable to load attendance.";

export default function Attendance() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const now = new Date(), year = now.getFullYear(), month = now.getMonth();
  useEffect(() => { studentModel.getMyAttendance().then((response) => setData(response?.data)).catch((error) => toast.error(message(error))).finally(() => setLoading(false)); }, []);
  const days = useMemo(() => {
    const values = new Map((data?.attendance || []).map((item) => [item.attendance_date, item.status]));
    return Array.from({ length: new Date(year, month + 1, 0).getDate() }, (_, index) => { const day = index + 1; const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`; return { day, status: values.get(date) || (new Date(year, month, day).getDay() === 0 ? "H" : day > now.getDate() ? "F" : null) }; });
  }, [data, month, year]);
  if (loading) return <PageContainer><Loader2 className="animate-spin mx-auto my-20" /></PageContainer>;
  const percent = Number(data?.attendance_percentage || 0), eligible = data?.eligibility?.eligible ?? percent >= 75;
  const trend = (data?.monthly_trend || []).map((item) => ({ month: item.month_label, percent: item.attendance_percentage }));
  const offset = (new Date(year, month, 1).getDay() + 6) % 7;
  return <PageContainer><PageHeader eyebrow="Student Portal" title="My Attendance" description="Daily attendance and monthly trend from your student record." />
    {!eligible && <div className="mb-5 flex gap-3 p-4 rounded-md bg-warning/10 border border-warning/30"><AlertTriangle className="text-warning" /><div><b className="text-sm">Attendance below 75%</b><p className="text-xs text-muted-foreground">Maintain at least {data?.eligibility?.minimum_percentage || 75}% attendance.</p></div></div>}
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6"><KpiCard label="Present" value={data?.present || 0} icon={<CalendarCheck />} tone="success" /><KpiCard label="Absent" value={data?.absent || 0} icon={<CalendarCheck />} tone="warning" /><KpiCard label="On Leave" value={data?.on_leave || 0} icon={<CalendarCheck />} tone="info" /><KpiCard label="Attendance %" value={`${percent}%`} icon={<CalendarCheck />} tone="primary" /></div>
    <div className="grid lg:grid-cols-3 gap-4"><Card className="lg:col-span-2"><CardHeader><CardTitle>{now.toLocaleString("en-IN", { month: "long", year: "numeric" })}</CardTitle><CardDescription>P · A · L · H (Holiday) · Future</CardDescription></CardHeader><CardContent><div className="grid grid-cols-7 gap-1.5 text-center text-xs text-muted-foreground mb-2">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((name) => <div key={name}>{name}</div>)}</div><div className="grid grid-cols-7 gap-1.5">{Array.from({ length: offset }, (_, index) => <div key={index} />)}{days.map(({ day, status }) => <div title={data?.status_legend?.[status] || "Not marked"} key={day} className={`aspect-square rounded-md border flex flex-col items-center justify-center text-xs ${colors[status] || "border-dashed text-muted-foreground"}`}><span>{day}</span>{status && status !== "F" && <small>{status}</small>}</div>)}</div></CardContent></Card>
      <Card><CardHeader><CardTitle>Last 4 Months</CardTitle><CardDescription>Attendance % trend</CardDescription></CardHeader><CardContent><ResponsiveContainer width="100%" height={220}><LineChart data={trend}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" /><YAxis domain={[0, 100]} /><Tooltip /><Line dataKey="percent" stroke="var(--chart-1)" strokeWidth={2.5} /></LineChart></ResponsiveContainer><Badge variant="outline" className={eligible ? "text-success" : "text-warning"}>{eligible ? "Eligible" : "Below threshold"}</Badge></CardContent></Card></div>
  </PageContainer>;
}

import { Link } from "react-router-dom";
import { useEffect, useState } from "react";

import {
  PageContainer,
  PageHeader,
} from "../../components/page-shell";

import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";

import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Progress } from "../../components/ui/progress";
import { KpiCard } from "../../components/kpi-card";

import {
  ArrowRight,
  Bell,
  BookOpen,
  CalendarDays,
  ClipboardList,
  FileBox,
  IndianRupee,
  Library,
  Megaphone,
  Trophy,
} from "lucide-react";

import studentModel from "../../api/studentModel";


// ============================================================
// HELPERS
// ============================================================

const formatDate = (value) =>
  value
    ? new Date(`${value}`.slice(0, 10)).toLocaleDateString(
        "en-IN",
        {
          day: "2-digit",
          month: "short",
          year: "numeric",
        }
      )
    : "—";


const currency = (value) =>
  new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(Number(value || 0));


const Empty = ({ text }) => (
  <div className="text-xs text-muted-foreground text-center p-4">
    {text}
  </div>
);

const getNoteCategory = (note) =>
  note?.category?.name || note?.category || "Notice";


// ============================================================
// DASHBOARD
// ============================================================

export default function Dashboard() {

  // ==========================================================
  // STATE
  // ==========================================================

  const [dashboard, setDashboard] = useState(null);
  const [error, setError] = useState("");


  // ==========================================================
  // LOAD DASHBOARD
  // ==========================================================

  const loadDashboard = () => {

    setError("");

    studentModel
      .getMyDashboard()
      .then((data) => {

        console.log(
          "Student Dashboard API:",
          data
        );

        setDashboard(data);

      })
      .catch((requestError) => {

        console.error(
          "Student Dashboard Error:",
          requestError
        );

        setError(
          requestError?.response?.data?.detail ||
          "Unable to load your dashboard."
        );

      });

  };


  // ==========================================================
  // INITIAL LOAD
  // ==========================================================

  useEffect(() => {

    loadDashboard();

  }, []);


  // ==========================================================
  // LOADING
  // ==========================================================

  if (!dashboard && !error) {

    return (
      <PageContainer>

        <div className="py-12 text-sm text-muted-foreground">
          Loading your dashboard…
        </div>

      </PageContainer>
    );

  }


  // ==========================================================
  // DATA
  // ==========================================================

  const student =
    dashboard?.student || {};

  const summary =
    dashboard?.summary || {};

  const fees =
    dashboard?.fees || {};

  const upcomingAssignments =
    dashboard?.upcoming_assignments || [];

  const latestResults =
    dashboard?.latest_results || [];

  const studyMaterials =
    dashboard?.study_materials || [];

  // `communication_notes` is the current dashboard response field. Retain
  // `notes` as a fallback while older backend deployments are upgraded.
  const portalNotes = Array.isArray(dashboard?.communication_notes)
    ? dashboard.communication_notes
    : Array.isArray(dashboard?.notes)
      ? dashboard.notes
      : [];

  // Empty legacy arrays are returned alongside `notes`, so prefer them only
  // when they actually contain records.
  const calendar = Array.isArray(dashboard?.calendar) && dashboard.calendar.length
    ? dashboard.calendar
    : portalNotes.filter((note) =>
        ["event", "events", "calendar", "holiday", "holidays", "academic"].includes(
          getNoteCategory(note).toLowerCase()
        )
      );

  const notices = Array.isArray(dashboard?.notices) && dashboard.notices.length
    ? dashboard.notices
    : portalNotes.filter(
        (note) =>
          !["event", "events", "calendar", "holiday", "holidays", "academic"].includes(
            getNoteCategory(note).toLowerCase()
          )
      );


  // ==========================================================
  // CLASS
  // ==========================================================

  const classLabel = [
    student?.class_name,
    student?.section_name,
  ]
    .filter(Boolean)
    .join(" - ");


  // ==========================================================
  // FEE VALUES
  // ==========================================================

  const totalFee =
    Number(fees?.total_amount || 0);

  const paidFee =
    Number(fees?.paid_amount || 0);

  const balanceFee =
    Number(fees?.balance_amount || 0);

  const lateFee =
    Number(fees?.late_fee || 0);


  // ==========================================================
  // FEE PROGRESS
  // ==========================================================

  const paidPercent =
    totalFee > 0
      ? Math.min(
          Math.max(
            (paidFee / totalFee) * 100,
            0
          ),
          100
        )
      : 0;


  // ==========================================================
  // RENDER
  // ==========================================================

  return (

    <PageContainer>

      {/* ======================================================
          HEADER
      ====================================================== */}

      <PageHeader
        eyebrow="Student Portal"
        title={`Hi ${
          student?.full_name?.split(" ")[0] ||
          "Student"
        } 👋`}
        description={
          student
            ? `Class ${
                classLabel || "Not assigned"
              } · ${student.session_year}`
            : "Your academic overview"
        }
      />


      {/* ======================================================
          ERROR
      ====================================================== */}

      {error && (

        <div className="mb-6 flex items-center justify-between rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">

          <span>
            {error}
          </span>

          <Button
            variant="outline"
            size="sm"
            onClick={loadDashboard}
          >
            Retry
          </Button>

        </div>

      )}


      {dashboard && (

        <>

          {/* ==================================================
              KPI CARDS
          ================================================== */}

          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">

            <KpiCard
              label="Attendance"
              value={`${
                summary.attendance_percentage ?? 0
              }%`}
              icon={
                <CalendarDays className="h-5 w-5" />
              }
              tone="success"
            />


            <KpiCard
              label="Pending Assignments"
              value={
                summary.pending_assignments ?? 0
              }
              icon={
                <ClipboardList className="h-5 w-5" />
              }
              tone="warning"
            />


            <KpiCard
              label="Upcoming Exams"
              value={
                summary.upcoming_exams ?? 0
              }
              icon={
                <BookOpen className="h-5 w-5" />
              }
              tone="info"
            />


            <KpiCard
              label="Study Materials"
              value={
                summary.study_materials ?? 0
              }
              icon={
                <FileBox className="h-5 w-5" />
              }
              tone="primary"
            />

          </div>


          {/* ==================================================
              ASSIGNMENTS + FEES
          ================================================== */}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-6">


            {/* ================================================
                UPCOMING ASSIGNMENTS
            ================================================= */}

            <Card className="lg:col-span-2 border-border/60">

              <CardHeader className="pb-2 flex-row items-center justify-between space-y-0">

                <div>

                  <CardTitle className="font-display text-base">
                    Upcoming Assignments
                  </CardTitle>

                  <CardDescription>
                    {summary.pending_assignments ?? 0} active
                  </CardDescription>

                </div>


                <Button
                  variant="ghost"
                  size="sm"
                  asChild
                >

                  <Link to="/student/assignments">

                    All

                    <ArrowRight className="h-3.5 w-3.5" />

                  </Link>

                </Button>

              </CardHeader>


              <CardContent className="space-y-2">

                {upcomingAssignments.map(
                  (item) => (

                    <Link
                      key={item.assignment_uuid}
                      to="/student/assignments"
                      className="flex items-center gap-3 p-2.5 border rounded-md hover:bg-muted/40"
                    >

                      <div className="flex-1 min-w-0">

                        <div className="text-sm font-medium truncate">
                          {item.title}
                        </div>

                        <div className="text-[11px] text-muted-foreground">

                          {item.subject_name || "Subject"}

                          {" · due "}

                          {formatDate(
                            item.due_date
                          )}

                        </div>

                      </div>


                      <Badge
                        variant="outline"
                        className="text-[10px]"
                      >
                        {item.status}
                      </Badge>

                    </Link>

                  )
                )}


                {!upcomingAssignments.length && (

                  <Empty
                    text="No pending assignments."
                  />

                )}

              </CardContent>

            </Card>


            {/* ================================================
                FEES
            ================================================= */}

            <Card className="border-border/60">

              <CardHeader className="pb-3 flex-row items-center justify-between space-y-0">

                <div>

                  <CardTitle className="font-display text-base flex items-center gap-2">

                    <IndianRupee className="h-4 w-4" />

                    Fees

                  </CardTitle>

                  <CardDescription>
                    Your fee details for{" "}
                    {student?.session_year || "current session"}
                  </CardDescription>

                </div>


                <Button
                  variant="outline"
                  size="sm"
                  asChild
                >

                  <Link to="/student/fees">
                    View
                  </Link>

                </Button>

              </CardHeader>


              <CardContent className="space-y-3">


                {/* ==========================================
                    TOTAL FEE
                ========================================== */}

                <div className="rounded-xl border bg-background p-3">

                  <div className="flex items-center justify-between">

                    <div>

                      <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                        Total Fee
                      </p>

                      <p className="mt-1 text-2xl font-semibold">
                        {currency(totalFee)}
                      </p>

                    </div>


                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-slate-100 text-slate-700">

                      <IndianRupee className="h-4 w-4" />

                    </div>

                  </div>

                </div>


                {/* ==========================================
                    FEES PAID
                ========================================== */}

                <div className="rounded-xl border bg-background p-3">

                  <div className="flex items-center justify-between">

                    <div>

                      <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                        Fees Paid
                      </p>

                      <p className="mt-1 text-2xl font-semibold text-green-600">
                        {currency(paidFee)}
                      </p>

                    </div>


                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-green-50 text-green-600">

                      <IndianRupee className="h-4 w-4" />

                    </div>

                  </div>

                </div>


                {/* ==========================================
                    FEES DUE
                ========================================== */}

                <div className="rounded-xl border bg-background p-3">

                  <div className="flex items-center justify-between">

                    <div>

                      <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                        Fees Due
                      </p>

                      <p
                        className={`mt-1 text-2xl font-semibold ${
                          balanceFee > 0
                            ? "text-orange-600"
                            : "text-green-600"
                        }`}
                      >
                        {currency(balanceFee)}
                      </p>

                    </div>


                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-orange-50 text-orange-500">

                      <IndianRupee className="h-4 w-4" />

                    </div>

                  </div>

                </div>


                {/* ==========================================
                    LATE FEE
                ========================================== */}

                <div className="rounded-xl border bg-background p-3">

                  <div className="flex items-center justify-between">

                    <div>

                      <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                        Late Fee
                      </p>

                      <p className="mt-1 text-2xl font-semibold">
                        {currency(lateFee)}
                      </p>

                    </div>


                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-sky-50 text-sky-600">

                      <IndianRupee className="h-4 w-4" />

                    </div>

                  </div>

                </div>


                {/* ==========================================
                    PROGRESS
                ========================================== */}

                <div className="rounded-xl border bg-muted/20 p-3">

                  <div className="flex items-center justify-between mb-2">

                    <div>

                      <p className="text-sm font-medium">
                        Fee Progress
                      </p>

                      <p className="text-[11px] text-muted-foreground">
                        {Math.round(paidPercent)}% paid
                      </p>

                    </div>


                    <span className="text-xs font-semibold">

                      {currency(paidFee)}
                      {" / "}
                      {currency(totalFee)}

                    </span>

                  </div>


                  <Progress
                    value={paidPercent}
                    className="h-2"
                  />


                  {/* BALANCE */}

                  <div className="mt-3">

                    {balanceFee > 0 ? (

                      <div className="text-xs text-muted-foreground">

                        Balance{" "}

                        <span className="font-semibold text-foreground">
                          {currency(balanceFee)}
                        </span>

                        {fees.next_due_date && (
                          <>
                            {" · Due "}
                            {formatDate(
                              fees.next_due_date
                            )}
                          </>
                        )}

                      </div>

                    ) : (

                      <div className="text-xs font-medium text-green-600">
                        All fees paid
                      </div>

                    )}

                  </div>


                  {/* LATE FEE */}

                  {lateFee > 0 && (

                    <div className="mt-2 text-xs text-muted-foreground">

                      Late Fee{" "}

                      <span className="font-semibold text-foreground">
                        {currency(lateFee)}
                      </span>

                    </div>

                  )}


                  {/* PAY NOW */}

                  {balanceFee > 0 && (

                    <Button
                      className="mt-4 w-full gradient-primary border-0"
                      asChild
                    >

                      <Link to="/student/fees">
                        Pay Now
                      </Link>

                    </Button>

                  )}


                  {/* FULLY PAID */}

                  {balanceFee <= 0 && (

                    <Button
                      variant="outline"
                      className="mt-4 w-full"
                      asChild
                    >

                      <Link to="/student/fees">
                        View Fee Details
                      </Link>

                    </Button>

                  )}

                </div>

              </CardContent>

            </Card>

          </div>


          {/* ==================================================
              RESULTS / MATERIALS / CALENDAR
          ================================================== */}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-6">


            {/* ================================================
                LATEST RESULTS
            ================================================= */}

            <Card className="border-border/60">

              <CardHeader className="pb-2 flex-row items-center justify-between space-y-0">

                <CardTitle className="font-display text-base flex items-center gap-2">

                  <Trophy className="h-4 w-4" />

                  Latest Results

                </CardTitle>


                <Button
                  variant="ghost"
                  size="sm"
                  asChild
                >

                  <Link to="/student/results">

                    All

                    <ArrowRight className="h-3.5 w-3.5" />

                  </Link>

                </Button>

              </CardHeader>


              <CardContent className="space-y-2">

                {latestResults.map(
                  (item) => (

                    <div
                      key={item.result_uuid}
                      className="flex justify-between text-sm border-b py-1.5"
                    >

                      <span>
                        {item.grade || "Result"}
                      </span>

                      <span className="font-semibold">
                        {item.percentage}%
                      </span>

                    </div>

                  )
                )}


                {!latestResults.length && (

                  <Empty
                    text="No published results."
                  />

                )}

              </CardContent>

            </Card>


            {/* ================================================
                STUDY MATERIALS
            ================================================= */}

            <Card className="border-border/60">

              <CardHeader className="pb-2 flex-row items-center justify-between space-y-0">

                <CardTitle className="font-display text-base flex items-center gap-2">

                  <FileBox className="h-4 w-4" />

                  Study Materials

                </CardTitle>


                <Button
                  variant="ghost"
                  size="sm"
                  asChild
                >

                  <Link to="/student/materials">

                    All

                    <ArrowRight className="h-3.5 w-3.5" />

                  </Link>

                </Button>

              </CardHeader>


              <CardContent className="space-y-2">

                {studyMaterials.map(
                  (item) => (

                    <div
                      key={item.material_uuid}
                      className="p-2 border rounded-md text-sm"
                    >

                      <div className="font-medium truncate">
                        {item.title}
                      </div>

                      <div className="text-[10px] text-muted-foreground">

                        {item.source_type}

                        {" · "}

                        {item.mime_type ||
                          "Document"}

                      </div>

                    </div>

                  )
                )}


                {!studyMaterials.length && (

                  <Empty
                    text="No study materials."
                  />

                )}

              </CardContent>

            </Card>


            {/* ================================================
                CALENDAR
            ================================================= */}

            <Card className="border-border/60">

              <CardHeader className="pb-2">

                <CardTitle className="font-display text-base flex items-center gap-2">

                  <CalendarDays className="h-4 w-4" />

                  Calendar

                </CardTitle>

              </CardHeader>


              <CardContent className="space-y-2">

                {calendar.map(
                  (item) => (

                    <div
                      key={
                        item.calendar_uuid ||
                        item.holiday_uuid ||
                        item.notes_uuid
                      }
                      className="p-2 border rounded-md text-sm"
                    >

                      <div className="font-medium">
                        {item.title}
                      </div>

                      <div className="text-[10px] text-muted-foreground">

                        {formatDate(
                          item.start_date
                        )}

                        {" · "}

                        {getNoteCategory(item)}

                      </div>

                    </div>

                  )
                )}


                {!calendar.length && (

                  <Empty
                    text="No upcoming events."
                  />

                )}

              </CardContent>

            </Card>

          </div>


          {/* ==================================================
              NOTICES
          ================================================== */}

          <Card className="border-border/60">

            <CardHeader className="pb-2 flex-row items-center justify-between space-y-0">

              <CardTitle className="font-display text-base flex items-center gap-2">

                <Megaphone className="h-4 w-4" />

                Notices

              </CardTitle>


              <Button
                variant="ghost"
                size="sm"
                asChild
              >

                <Link to="/student/notices">

                  All

                  <ArrowRight className="h-3.5 w-3.5" />

                </Link>

              </Button>

            </CardHeader>


            <CardContent className="space-y-2">

              {notices.map(
                (item) => (

                  <div
                    key={item.notice_uuid || item.notes_uuid}
                    className="flex items-center gap-3 p-2.5 border rounded-md"
                  >

                    <Badge
                      variant="outline"
                      className="text-[10px]"
                    >
                      {getNoteCategory(item)}
                    </Badge>


                    <div className="flex-1 text-sm">
                      {item.title}
                    </div>


                    <div className="text-[10px] text-muted-foreground">

                      {formatDate(
                        item.start_date
                      )}

                    </div>

                  </div>

                )
              )}


              {!notices.length && (

                <Empty
                  text="No active notices."
                />

              )}

            </CardContent>

          </Card>

        </>

      )}


      {/* ======================================================
          FOOTER
      ====================================================== */}

      <div className="mt-4 text-[10px] text-muted-foreground flex items-center gap-2">

        <Bell className="h-3 w-3" />

        Library, attendance and timetable available in the side menu.

        <Library className="h-3 w-3" />

      </div>

    </PageContainer>

  );

}

