import { useEffect, useState } from "react";
import { Images, X, CalendarDays, FolderOpen, Video, Loader2 } from "lucide-react";
import { getPortalAlbumDetail, getPortalAlbums } from "../../api/gallery";

const isVideo = (media) =>
  String(media?.media_type || "").toUpperCase() === "VIDEO" ||
  String(media?.mime_type || "").startsWith("video/");

const normalizeAlbum = (album) => ({
  uuid: album.album_uuid,
  title: album.title,
  category: album.category,
  date: album.album_date,
  description: album.description,
  mediaCount: album.media_count ?? 0,
  cover: album.cover_media?.file_url,
  coverIsVideo: isVideo(album.cover_media),
  media: [],
});

export default function Gallery() {
  const [albums, setAlbums] = useState([]);
  const [selectedAlbum, setSelectedAlbum] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isAlbumLoading, setIsAlbumLoading] = useState(false);
  const [error, setError] = useState(null);

  const loadAlbums = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await getPortalAlbums({ page: 1, pageSize: 100 });
      setAlbums((response.data || []).map(normalizeAlbum));
    } catch (err) {
      setError(err?.response?.data?.detail || "Couldn't load the gallery. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { loadAlbums(); }, []);

  const openAlbum = async (album) => {
    setSelectedAlbum(album);
    setIsAlbumLoading(true);
    try {
      const detail = await getPortalAlbumDetail(album.uuid);
      setSelectedAlbum({
        ...album,
        title: detail.title || album.title,
        date: detail.album_date || album.date,
        media: (detail.media || []).map((media) => ({
          uuid: media.media_uuid,
          url: media.file_url,
          video: isVideo(media),
        })),
      });
    } catch (err) {
      setSelectedAlbum(null);
      setError(err?.response?.data?.detail || "Couldn't open this album.");
    } finally {
      setIsAlbumLoading(false);
    }
  };

  return <div className="min-h-screen bg-[#f7fafc] px-4 py-6 sm:px-6 lg:px-7">
    <div className="mb-7"><p className="mb-1 text-[13px] font-medium uppercase tracking-[0.08em] text-[#173f70]">Student Portal</p><h1 className="text-[32px] font-medium leading-[1.15] tracking-[-0.02em] text-[#07182d]">Gallery</h1><p className="mt-1 text-[16px] text-[#48617d]">Photos and videos uploaded by the admin team for student viewing.</p></div>
    {isLoading ? <LoadingState /> : error ? <ErrorState message={error} onRetry={loadAlbums} /> : albums.length === 0 ? <EmptyState /> : <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3">{albums.map((album) => <GalleryCard key={album.uuid} album={album} onOpen={() => openAlbum(album)} />)}</div>}
    {selectedAlbum && <AlbumModal album={selectedAlbum} isLoading={isAlbumLoading} onClose={() => setSelectedAlbum(null)} />}
  </div>;
}

function GalleryCard({ album, onOpen }) { return <div className="overflow-hidden rounded-[15px] border border-[#dce4ea] bg-white shadow-[0_1px_3px_rgba(15,23,42,0.08)]"><div className="relative h-[278px] overflow-hidden bg-[#e9eef2]">{album.cover ? album.coverIsVideo ? <video src={album.cover} className="h-full w-full object-cover" muted /> : <img src={album.cover} alt={album.title} className="h-full w-full object-cover" /> : <div className="flex h-full items-center justify-center text-[#8292a2]"><Images size={45} /></div>}<div className="absolute left-[14px] top-[13px]"><span className="rounded-[9px] bg-[#07336d] px-3 py-[5px] text-[12px] font-semibold text-white">{album.category}</span></div></div><div className="px-[17px] pb-[17px] pt-[18px]"><h2 className="text-[18px] font-medium text-[#081a31]">{album.title}</h2><div className="mt-1 text-[13px] text-[#55708c]">{album.date} · {album.mediaCount} media files</div><p className="mt-[14px] min-h-[42px] text-[16px] leading-[1.45] text-[#536b86]">{album.description || "No description added."}</p><button type="button" onClick={onOpen} className="mt-[13px] flex h-[37px] w-full items-center justify-center gap-2 rounded-[9px] border border-[#d5e0e8] bg-[#f8fbfd] text-[14px] font-medium text-[#07182d] hover:bg-[#eef4f8]"><FolderOpen size={18} />Open Album</button></div></div>; }

function AlbumModal({ album, isLoading, onClose }) { return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 px-0 sm:px-4" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="max-h-[92vh] w-full overflow-hidden bg-[#f8fbfd] shadow-2xl sm:max-w-[1150px] sm:rounded-[12px]"><div className="flex items-center justify-between px-5 py-5 sm:px-7"><div><h2 className="text-[21px] font-semibold text-[#0a1d32]">{album.title}</h2><div className="mt-1 flex items-center gap-2 text-[13px] text-[#58718b]"><CalendarDays size={15}/>{album.date}<span>·</span><Images size={15}/>{album.mediaCount} media files</div></div><button type="button" onClick={onClose} aria-label="Close album" className="p-2"><X size={22}/></button></div><div className="max-h-[calc(92vh-92px)] overflow-y-auto px-5 pb-6 sm:px-7">{isLoading ? <LoadingState /> : <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">{album.media.map((item, index) => <div key={item.uuid} className="relative aspect-[1.75/1] overflow-hidden rounded-[9px] bg-[#e9eef2]">{item.video ? <video src={item.url} controls className="h-full w-full object-cover"/> : <img src={item.url} alt={`${album.title} ${index + 1}`} className="h-full w-full object-cover" loading="lazy"/>}{item.video && <Video className="absolute left-2 top-2 text-white" size={18}/>}</div>)}</div>}</div></div></div>; }
function LoadingState() { return <div className="flex items-center justify-center gap-2 py-16 text-[#566d85]"><Loader2 size={18} className="animate-spin"/>Loading gallery...</div>; }
function ErrorState({ message, onRetry }) { return <div className="rounded-[15px] border border-dashed border-[#f1c2c2] bg-white px-5 py-16 text-center"><p className="text-[#7a2020]">{message}</p><button type="button" onClick={onRetry} className="mt-5 rounded-[9px] bg-[#0b3c75] px-4 py-2 text-sm font-semibold text-white">Try Again</button></div>; }
function EmptyState() { return <div className="rounded-[15px] border border-dashed border-[#cfdbe4] bg-white px-5 py-16 text-center text-[#62778d]"><Images className="mx-auto mb-3"/>No gallery albums are available yet.</div>; }

import { Fragment, useEffect, useMemo, useState } from "react";
import { CalendarDays, Loader2 } from "lucide-react";

import { PageContainer, PageHeader } from "../../components/page-shell";
import { Card, CardContent } from "../../components/ui/card";
import { Badge } from "../../components/ui/badge";

import studentModel from "../../api/studentModel";
import useSessionStore from "../../store/sessionStore";

// ============================================================
// Constants
// ============================================================

const DAYS = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday",
];

const TYPES = [
  { id: "regular", label: "Regular Timetable" },
  { id: "summer", label: "Summer Timetable" },
  { id: "examination", label: "Examination Timetable" },
  { id: "additional", label: "Additional Timetable" },
];

const EMPTY_TYPE_DATA = {
  record: null,
  records: [],
  schedule: [],
};

const DAY_SHORT = {
  Monday: "Mon",
  Tuesday: "Tue",
  Wednesday: "Wed",
  Thursday: "Thu",
  Friday: "Fri",
  Saturday: "Sat",
  Sunday: "Sun",
};

const SUBJECT_STYLES = [
  {
    bg: "bg-blue-500/10",
    text: "text-blue-700 dark:text-blue-300",
  },
  {
    bg: "bg-emerald-500/10",
    text: "text-emerald-700 dark:text-emerald-300",
  },
  {
    bg: "bg-amber-500/10",
    text: "text-amber-700 dark:text-amber-300",
  },
  {
    bg: "bg-fuchsia-500/10",
    text: "text-fuchsia-700 dark:text-fuchsia-300",
  },
  {
    bg: "bg-rose-500/10",
    text: "text-rose-700 dark:text-rose-300",
  },
  {
    bg: "bg-cyan-500/10",
    text: "text-cyan-700 dark:text-cyan-300",
  },
  {
    bg: "bg-violet-500/10",
    text: "text-violet-700 dark:text-violet-300",
  },
];

// ============================================================
// Helpers
// ============================================================

function subjectStyle(name = "") {
  let hash = 0;

  for (let i = 0; i < name.length; i += 1) {
    hash =
      name.charCodeAt(i) +
      ((hash << 5) - hash);
  }

  return SUBJECT_STYLES[
    Math.abs(hash) % SUBJECT_STYLES.length
  ];
}

// ------------------------------------------------------------
// Normalize timetable rows
//
// Supports:
//
// Regular / Summer:
// {
//   day,
//   period,
//   start_time,
//   end_time,
//   subject,
//   teacher
// }
//
// Additional:
// {
//   Day,
//   Period,
//   Start Time,
//   End Time,
//   Subject,
//   Teacher
// }
// ------------------------------------------------------------

function scheduleOf(rows = []) {
  if (!Array.isArray(rows)) {
    return [];
  }

  return rows
    .map((row) => ({
      ...row,

      day:
        row?.day ||
        row?.Day ||
        "",

      period: Number(
        row?.period ||
        row?.Period ||
        0
      ),

      startTime:
        row?.start_time ||
        row?.["Start Time"] ||
        row?.startTime ||
        "",

      endTime:
        row?.end_time ||
        row?.["End Time"] ||
        row?.endTime ||
        "",

      subject:
        row?.subject ||
        row?.Subject ||
        "—",

      teacher:
        row?.teacher ||
        row?.Teacher ||
        "—",

      room:
        row?.room ||
        row?.Room ||
        row?.classroom ||
        row?.room_name ||
        "—",
    }))
    .filter(
      (row) =>
        row.day &&
        Number.isFinite(row.period) &&
        row.period > 0
    )
    .sort((a, b) => {
      if (a.period !== b.period) {
        return a.period - b.period;
      }

      return String(a.day).localeCompare(
        String(b.day)
      );
    });
}

// ============================================================
// Examination helpers
// ============================================================

function examinationRows(rows = []) {
  if (!Array.isArray(rows)) {
    return [];
  }

  return [...rows].sort((a, b) => {
    const dateA = new Date(
      `${a?.exam_date || ""}T${a?.start_time || "00:00:00"}`
    );

    const dateB = new Date(
      `${b?.exam_date || ""}T${b?.start_time || "00:00:00"}`
    );

    return dateA - dateB;
  });
}

// ============================================================
// Format date
// ============================================================

function formatExamDate(date) {
  if (!date) {
    return "—";
  }

  const parsed = new Date(date);

  if (Number.isNaN(parsed.getTime())) {
    return date;
  }

  return parsed.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

// ============================================================
// Main Component
// ============================================================

export default function MyTimetable() {
  const activeSession = useSessionStore(
    (state) => state.sessionYear
  );

  const [activeType, setActiveType] =
    useState("regular");

  const [profile, setProfile] =
    useState(null);

  const [typeData, setTypeData] =
    useState({});

  const [loading, setLoading] =
    useState(true);

  const [error, setError] =
    useState("");

  // ==========================================================
  // Load timetable
  //
  // ONE API:
  // GET /student-portal/my-timetable
  //
  // session_year comes from active session.
  // ==========================================================

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setLoading(true);
      setError("");

      try {
        const response =
          await studentModel.getMyTimetable();

        if (cancelled) {
          return;
        }

        // ----------------------------------------------------
        // API response:
        //
        // {
        //   success: true,
        //   message: "...",
        //   data: {
        //     student_uuid,
        //     class_uuid,
        //     class_name,
        //     section_uuid,
        //     section_name,
        //     academic_year,
        //     timetables: {
        //       regular: [],
        //       summer: [],
        //       examination: [],
        //       additional: []
        //     }
        //   }
        // }
        // ----------------------------------------------------

        const data =
          response?.data || {};

        const timetables =
          data?.timetables || {};

        const sessionYear =
          data?.academic_year ||
          activeSession ||
          "";

        // ----------------------------------------------------
        // Student profile
        // ----------------------------------------------------

        const student = {
          student_uuid:
            data?.student_uuid,

          class_uuid:
            data?.class_uuid,

          class_name:
            data?.class_name,

          section_uuid:
            data?.section_uuid,

          section_name:
            data?.section_name,

          session_year:
            sessionYear,
        };

        // ----------------------------------------------------
        // Regular
        // ----------------------------------------------------

        const regularRows =
          Array.isArray(timetables?.regular)
            ? timetables.regular
            : [];

        // ----------------------------------------------------
        // Summer
        // ----------------------------------------------------

        const summerRows =
          Array.isArray(timetables?.summer)
            ? timetables.summer
            : [];

        // ----------------------------------------------------
        // Examination
        // ----------------------------------------------------

        const examination =
          Array.isArray(
            timetables?.examination
          )
            ? timetables.examination
            : [];

        // ----------------------------------------------------
        // Additional
        // ----------------------------------------------------

        const additionalRows =
          Array.isArray(
            timetables?.additional
          )
            ? timetables.additional
            : [];

        // ----------------------------------------------------
        // Build state
        // ----------------------------------------------------

        const selectedByType = {
          regular: {
            record:
              regularRows[0] || null,

            records:
              regularRows,

            schedule:
              scheduleOf(regularRows),
          },

          summer: {
            record:
              summerRows[0] || null,

            records:
              summerRows,

            schedule:
              scheduleOf(summerRows),
          },

          examination: {
            record:
              examination[0] || null,

            records:
              examinationRows(examination),

            // Examination timetable doesn't use
            // regular periods.
            schedule: [],
          },

          additional: {
            record:
              additionalRows[0] || null,

            records:
              additionalRows,

            schedule:
              scheduleOf(additionalRows),
          },
        };

        if (!cancelled) {
          setProfile(student);
          setTypeData(selectedByType);
        }
      } catch (err) {
        if (!cancelled) {
          setError(
            err?.response?.data?.detail ||
              err?.response?.data?.message ||
              err?.message ||
              "Could not load your timetable."
          );
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    }

    load();

    return () => {
      cancelled = true;
    };
  }, [activeSession]);

  // ==========================================================
  // Current timetable
  // ==========================================================

  const current =
    typeData[activeType] ||
    EMPTY_TYPE_DATA;

  const schedule =
    current.schedule || [];

  const meta =
    current.record || null;

  // ==========================================================
  // Weekly grid
  // ==========================================================

  const grid = useMemo(() => {
    const availableDays =
      new Set(
        schedule.map(
          (row) => row.day
        )
      );

    const days =
      DAYS.filter(
        (day) =>
          availableDays.has(day)
      );

    const periodMap =
      new Map();

    const cells =
      new Map();

    schedule.forEach((row) => {
      if (!periodMap.has(row.period)) {
        periodMap.set(
          row.period,
          row
        );
      }

      cells.set(
        `${row.day}:${row.period}`,
        row
      );
    });

    return {
      days,
      periods: [
        ...periodMap.values(),
      ].sort(
        (a, b) =>
          a.period - b.period
      ),
      cells,
    };
  }, [schedule]);

  // ==========================================================
  // Today
  // ==========================================================

  const today =
    DAYS[
      (new Date().getDay() + 6) %
        7
    ];

  // ==========================================================
  // Labels
  // ==========================================================

  const classLabel = profile
    ? `${profile.class_name || "Class"}${
        profile.section_name
          ? `-${profile.section_name}`
          : ""
      }`
    : "Your class";

  const activeTypeLabel =
    TYPES.find(
      (type) =>
        type.id === activeType
    )?.label ||
    "Timetable";

  // ==========================================================
  // Render
  // ==========================================================

  return (
    <PageContainer>
      {/* =====================================================
          Header
      ===================================================== */}

      <PageHeader
        eyebrow="Student Portal"
        title="My Weekly Timetable"
        description={`${classLabel} · ${
          profile?.session_year ||
          activeSession ||
          "Academic Year"
        } · Read-only`}
      />

      {/* =====================================================
          Timetable Type Tabs
      ===================================================== */}

      <div className="mb-4 flex gap-1 overflow-x-auto rounded-lg bg-muted p-1">
        {TYPES.map((type) => {
          const count =
            typeData[type.id]
              ?.records?.length || 0;

          return (
            <button
              key={type.id}
              type="button"
              onClick={() =>
                setActiveType(
                  type.id
                )
              }
              className={`whitespace-nowrap rounded-md px-4 py-2 text-sm font-medium transition-colors ${
                activeType === type.id
                  ? "bg-background text-foreground shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {type.label}

              {count > 0 && (
                <span className="ml-2 rounded-full bg-primary/10 px-1.5 py-0.5 text-[10px] text-primary">
                  {count}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* =====================================================
          Loading
      ===================================================== */}

      {loading ? (
        <Card>
          <CardContent className="flex items-center justify-center gap-2 py-16 text-sm text-muted-foreground">
            <Loader2 className="h-5 w-5 animate-spin" />

            Loading timetable...
          </CardContent>
        </Card>
      ) : error ? (
        /* ===================================================
           Error
           =================================================== */

        <Card>
          <CardContent className="py-16 text-center text-sm text-destructive">
            {String(error)}
          </CardContent>
        </Card>
      ) : activeType ===
        "examination" ? (
        /* ===================================================
           Examination Timetable
           =================================================== */

        current.records.length ? (
          <Card className="overflow-hidden rounded-2xl border-border/70 shadow-sm">
            {/* Header */}

            <div className="flex items-center justify-between gap-4 border-b bg-muted/20 px-5 py-4">
              <div>
                <div className="text-base font-semibold">
                  Examination Timetable ·{" "}
                  {classLabel}
                </div>

                <div className="text-sm text-muted-foreground">
                  {
                    profile?.session_year
                  }{" "}
                  ·{" "}
                  {
                    current.records
                      .length
                  }{" "}
                  examinations
                </div>
              </div>

              <Badge
                variant="outline"
                className="border-emerald-500/20 bg-emerald-500/10 text-emerald-700"
              >
                Scheduled
              </Badge>
            </div>

            {/* Examination Table */}

            <CardContent className="overflow-auto p-0">
              <div className="min-w-[950px]">
                {/* Table Header */}

                <div className="grid grid-cols-7 border-b bg-muted/30 text-xs font-semibold uppercase tracking-wide">
                  <div className="p-4">
                    Date
                  </div>

                  <div className="p-4">
                    Day
                  </div>

                  <div className="p-4">
                    Exam
                  </div>

                  <div className="p-4">
                    Subject
                  </div>

                  <div className="p-4">
                    Paper
                  </div>

                  <div className="p-4">
                    Time
                  </div>

                  <div className="p-4">
                    Room
                  </div>
                </div>

                {/* Rows */}

                {current.records.map(
                  (
                    exam,
                    index
                  ) => (
                    <div
                      key={
                        exam.paper_uuid ||
                        `${exam.exam_uuid}-${index}`
                      }
                      className="grid grid-cols-7 border-b text-sm transition-colors hover:bg-muted/20"
                    >
                      {/* Date */}

                      <div className="p-4 font-medium">
                        {formatExamDate(
                          exam.exam_date
                        )}
                      </div>

                      {/* Day */}

                      <div className="p-4">
                        {exam.day ||
                          "—"}
                      </div>

                      {/* Exam */}

                      <div className="p-4 font-medium">
                        {exam.exam_name ||
                          "—"}
                      </div>

                      {/* Subject */}

                      <div className="p-4 font-semibold">
                        {exam.subject ||
                          "—"}
                      </div>

                      {/* Paper */}

                      <div className="p-4">
                        {exam.paper_name ||
                          "—"}
                      </div>

                      {/* Time */}

                      <div className="p-4">
                        {exam.start_time ||
                          "—"}

                        {exam.duration_minutes && (
                          <div className="mt-1 text-xs text-muted-foreground">
                            {
                              exam.duration_minutes
                            }{" "}
                            minutes
                          </div>
                        )}
                      </div>

                      {/* Room */}

                      <div className="p-4">
                        {exam.room_name ||
                          "—"}
                      </div>
                    </div>
                  )
                )}
              </div>
            </CardContent>
          </Card>
        ) : (
          /* No examination */

          <Card>
            <CardContent className="py-16 text-center">
              <CalendarDays className="mx-auto mb-3 h-8 w-8 text-muted-foreground" />

              <div className="font-medium">
                No examination timetable
                found
              </div>

              <div className="mt-1 text-sm text-muted-foreground">
                No examinations are
                scheduled for{" "}
                {classLabel} in{" "}
                {profile?.session_year ||
                  activeSession}.
              </div>
            </CardContent>
          </Card>
        )
      ) : !schedule.length &&
        current.records.length ? (
        /* ===================================================
           Records without weekly schedule
           =================================================== */

        <Card className="overflow-hidden rounded-2xl border-border/70 shadow-sm">
          <div className="border-b bg-muted/20 px-5 py-4">
            <div className="font-semibold">
              {activeTypeLabel}
            </div>

            <div className="text-sm text-muted-foreground">
              {classLabel} ·{" "}
              {profile?.session_year}
            </div>
          </div>

          <CardContent className="divide-y p-0">
            {current.records.map(
              (
                record,
                index
              ) => {
                const fileUrl =
                  record.file_url ||
                  record.file ||
                  record.document_url ||
                  record.url;

                return (
                  <div
                    key={
                      record.timetable_uuid ||
                      record.uuid ||
                      index
                    }
                    className="flex items-center justify-between gap-4 px-5 py-4"
                  >
                    <div>
                      <div className="font-medium">
                        {record.title ||
                          record.name ||
                          record.file_name ||
                          activeTypeLabel}
                      </div>

                      <div className="mt-1 text-xs text-muted-foreground">
                        {record.status ||
                          "Available"}
                      </div>
                    </div>

                    {fileUrl ? (
                      <a
                        href={fileUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="rounded-md border px-3 py-1.5 text-sm font-medium hover:bg-muted"
                      >
                        View
                      </a>
                    ) : (
                      <Badge variant="outline">
                        {record.status ||
                          "Available"}
                      </Badge>
                    )}
                  </div>
                );
              }
            )}
          </CardContent>
        </Card>
      ) : !schedule.length ? (
        /* ===================================================
           No timetable
           =================================================== */

        <Card>
          <CardContent className="py-16 text-center">
            <CalendarDays className="mx-auto mb-3 h-8 w-8 text-muted-foreground" />

            <div className="font-medium">
              No{" "}
              {activeTypeLabel.toLowerCase()}{" "}
              found
            </div>

            <div className="mt-1 text-sm text-muted-foreground">
              Nothing is available for{" "}
              {classLabel} in{" "}
              {profile?.session_year ||
                activeSession}.
            </div>
          </CardContent>
        </Card>
      ) : (
        /* ===================================================
           Weekly Timetable
           =================================================== */

        <Card className="overflow-hidden rounded-2xl border-border/70 shadow-sm">
          {/* Header */}

          <div className="flex items-center justify-between gap-4 border-b bg-muted/20 px-5 py-4">
            <div>
              <div className="text-base font-semibold">
                {activeTypeLabel} ·{" "}
                {classLabel}
              </div>

              <div className="text-sm text-muted-foreground">
                {profile?.session_year ||
                  activeSession}{" "}
                ·{" "}
                {grid.days.length}{" "}
                days ·{" "}
                {grid.periods.length}{" "}
                periods
              </div>
            </div>

            <Badge
              variant="outline"
              className="border-emerald-500/20 bg-emerald-500/10 text-emerald-700"
            >
              Active
            </Badge>
          </div>

          {/* Weekly Grid */}

          <CardContent className="overflow-auto p-0">
            <div
              className="grid min-w-[900px]"
              style={{
                gridTemplateColumns: `110px repeat(${grid.days.length}, 1fr)`,
              }}
            >
              {/* Period Header */}

              <div className="border-b border-r bg-slate-50 p-4 text-xs font-semibold uppercase tracking-wider text-slate-600 dark:bg-slate-900/40">
                Period
              </div>

              {/* Day Headers */}

              {grid.days.map(
                (day) => (
                  <div
                    key={day}
                    className={`border-b bg-slate-50 p-4 text-center text-xs font-semibold uppercase tracking-wider dark:bg-slate-900/40 ${
                      day === today
                        ? "text-primary"
                        : "text-slate-600"
                    }`}
                  >
                    {
                      DAY_SHORT[
                        day
                      ]
                    }

                    {day ===
                      today && (
                      <span className="ml-1 rounded bg-primary/10 px-1.5 py-0.5 text-[9px] font-medium normal-case">
                        Today
                      </span>
                    )}
                  </div>
                )
              )}

              {/* Period Rows */}

              {grid.periods.map(
                (period) => (
                  <Fragment
                    key={
                      period.period
                    }
                  >
                    {/* Period Time */}

                    <div className="flex flex-col justify-center border-b border-r p-4 text-sm font-semibold text-slate-600 dark:text-slate-300">
                      <span>
                        {period.startTime ||
                          `Period ${period.period}`}
                      </span>

                      {period.endTime && (
                        <span className="mt-1 text-xs font-normal text-muted-foreground">
                          {
                            period.endTime
                          }
                        </span>
                      )}
                    </div>

                    {/* Day Cells */}

                    {grid.days.map(
                      (day) => {
                        const cell =
                          grid.cells.get(
                            `${day}:${period.period}`
                          );

                        // Empty cell

                        if (!cell) {
                          return (
                            <div
                              key={`${day}-${period.period}`}
                              className="border-b bg-muted/10 p-2"
                            >
                              <div className="flex min-h-[76px] items-center justify-center text-xs text-muted-foreground">
                                —
                              </div>
                            </div>
                          );
                        }

                        const style =
                          subjectStyle(
                            cell.subject
                          );

                        return (
                          <div
                            key={`${day}-${period.period}`}
                            className={`border-b p-2 ${
                              day === today
                                ? "bg-primary/[0.03]"
                                : ""
                            }`}
                          >
                            <div
                              className={`min-h-[76px] rounded-xl border border-border/70 px-3 py-2 ${style.bg}`}
                            >
                              {/* Subject */}

                              <div
                                className={`text-sm font-semibold leading-tight ${style.text}`}
                              >
                                {
                                  cell.subject
                                }
                              </div>

                              {/* Teacher */}

                              {cell.teacher &&
                                cell.teacher !==
                                  "—" && (
                                  <div
                                    className={`mt-1 truncate text-xs opacity-80 ${style.text}`}
                                    title={
                                      cell.teacher
                                    }
                                  >
                                    {
                                      cell.teacher
                                    }
                                  </div>
                                )}

                              {/* Room */}

                              {cell.room &&
                                cell.room !==
                                  "—" && (
                                  <div
                                    className={`mt-0.5 truncate text-xs opacity-70 ${style.text}`}
                                    title={
                                      cell.room
                                    }
                                  >
                                    {
                                      cell.room
                                    }
                                  </div>
                                )}
                            </div>
                          </div>
                        );
                      }
                    )}
                  </Fragment>
                )
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </PageContainer>
  );
}

import { Link } from "react-router-dom";
import { PageContainer, PageHeader } from "../../components/page-shell";
import { KpiCard } from "../../components/kpi-card";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "../../components/ui/card";
import { Button } from "../../components/ui/button";
import { Badge } from "../../components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "../../components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../../components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "../../components/ui/table";
import { Progress } from "../../components/ui/progress";
import { BookOpen, CalendarDays, Trophy, Download, Clock, MapPin, FileText, Target, TrendingUp, Award } from "lucide-react";
import { useCurrentStudent } from "../../lib/student-ctx";
import { useEffect, useMemo, useState } from "react";
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, Legend, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from "recharts";
import { toast } from "sonner";
import studentModel from "../../api/studentModel";

// Route registration (add this in your router file, e.g. router.jsx):
//   import StudentExamsPage from "./pages/student/Exams";
//   { path: "student/exams", element: <StudentExamsPage /> },

const EXAM_TYPES = [
  { type: "Unit Test", count: 4, weight: "10%", description: "Short tests held every 4–6 weeks to check chapter-level understanding.", color: "bg-info/10 text-info border-info/20" },
  { type: "Mid-Term", count: 2, weight: "25%", description: "Half-syllabus written exams covering taught chapters of the term.", color: "bg-warning/15 text-warning border-warning/20" },
  { type: "Pre-Board", count: 1, weight: "15%", description: "Full-syllabus rehearsal for Class X & XII before board exams.", color: "bg-primary/10 text-primary border-primary/20" },
  { type: "Annual / Board", count: 1, weight: "50%", description: "Final assessment as per CBSE/ICSE board pattern.", color: "bg-success/10 text-success border-success/20" },
];

const ROOM_MAP = { Math: "F-11", Science: "F-12", English: "G-04", Social: "G-05", Hindi: "G-06" };
const TIME_SLOTS = ["09:00 AM – 12:00 PM", "09:00 AM – 11:00 AM", "01:00 PM – 04:00 PM"];

const grade = (pct) => pct >= 91 ? "A1" : pct >= 81 ? "A2" : pct >= 71 ? "B1" : pct >= 61 ? "B2" : pct >= 51 ? "C1" : pct >= 41 ? "C2" : "D";
const gpa = (pct) => pct >= 91 ? 10 : pct >= 81 ? 9 : pct >= 71 ? 8 : pct >= 61 ? 7 : pct >= 51 ? 6 : pct >= 41 ? 5 : 4;
const formatExamDate = (date) => date ? new Date(`${date}T00:00:00`).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }) : "Date TBD";
const formatExamTime = (time) => {
  if (!time) return "Time TBD";
  const [hours, minutes] = time.split(":");
  const value = new Date(`1970-01-01T${hours}:${minutes}:00`);
  return value.toLocaleTimeString("en-IN", { hour: "numeric", minute: "2-digit", hour12: true });
};

export default function StudentExamsPage() {
  const { student: me } = useCurrentStudent();
  const myClass = me?.class ?? "X";
  const [dashboard, setDashboard] = useState({});
  const [myExams, setMyExams] = useState([]);
  const [myMarks, setMyMarks] = useState([]);
  const [portalTypes, setPortalTypes] = useState([]);
  const [selectedExam, setSelectedExam] = useState("");

  useEffect(() => {
    let mounted = true;
    Promise.all([studentModel.getMyExamDashboard(), studentModel.getMyExamSchedule(), studentModel.getMyExamTypes(), studentModel.getMyExamResults()])
      .then(([dashboardData, scheduleData, typesData, resultsData]) => {
        if (!mounted) return;
        const resultRows = resultsData?.results ?? [];
        setDashboard(dashboardData ?? {});
        setMyExams((scheduleData?.exams ?? []).map((exam) => ({
          id: exam.exam_uuid,
          name: exam.exam_name,
          from: exam.from_date,
          to: exam.to_date,
          status: exam.status,
          subjects: exam.papers?.length ?? 0,
          class: myClass,
          papers: exam.papers ?? [],
        })));
        setPortalTypes((typesData?.exam_types ?? []).map((type) => ({
          type: type.name,
          count: type.exam_count ?? 0,
          weight: `${type.exam_count ?? 0} exams`,
          description: type.description || "No description available.",
          color: "bg-primary/10 text-primary border-primary/20",
        })));
        setMyMarks(resultRows.flatMap((result) => (result.subject_marks ?? []).map((mark) => ({
          id: `${result.result_uuid}-${mark.subject_uuid}`,
          examId: result.result_uuid,
          examName: result.exam_name,
          subject: mark.subject_name,
          obtained: mark.marks,
          max: mark.max_marks,
          isAbsent: mark.is_absent,
          grade: result.grade,
        }))));
        setSelectedExam(resultRows[0]?.result_uuid ?? "");
      })
      .catch(() => mounted && toast.error("Unable to load examination portal data."));
    return () => { mounted = false; };
  }, [myClass]);

  const examIds = useMemo(() => Array.from(new Set(myMarks.map((m) => m.examId))), [myMarks]);
  const examRows = myMarks.filter((m) => m.examId === selectedExam);
  const totalObt = examRows.reduce((s, m) => s + (m.obtained ?? 0), 0);
  const totalMax = examRows.reduce((s, m) => s + m.max, 0);
  const pct = totalMax > 0 ? Math.round((totalObt / totalMax) * 100) : 0;

  const upcoming = myExams.filter((e) => ["SCHEDULED", "IN PROGRESS"].includes(String(e.status).toUpperCase()));
  const completed = myExams.filter((e) => String(e.status).toUpperCase() === "COMPLETED");

  const radarData = examRows.map((m) => ({ subject: m.subject, score: Math.round(((m.obtained ?? 0) / m.max) * 100), fullMark: 100 }));
  const barData = examRows.map((m) => ({ subject: m.subject, obtained: m.obtained ?? 0, max: m.max }));

  return (
    <PageContainer>
      <PageHeader
        eyebrow="Student Portal"
        title="Exams & Results"
        description="Schedule, exam types and detailed performance reports."
        actions={
          <Button size="sm" className="gradient-primary border-0" onClick={() => toast.success("Admit card downloaded")}>
            <Download className="h-4 w-4" />Admit Card
          </Button>
        }
      />

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <KpiCard label="Upcoming Exams" value={dashboard.upcoming_exams ?? upcoming.length} icon={<CalendarDays className="h-5 w-5" />} tone="primary" />
        <KpiCard label="Completed" value={dashboard.completed_exams ?? completed.length} icon={<BookOpen className="h-5 w-5" />} tone="success" />
        <KpiCard label="Latest %" value={`${dashboard.latest_percentage ?? pct}%`} icon={<TrendingUp className="h-5 w-5" />} tone="info" />
        <KpiCard label="Overall Grade" value={dashboard.overall_grade ?? grade(pct)} icon={<Trophy className="h-5 w-5" />} tone="warning" />
      </div>

      <Tabs defaultValue="schedule" className="space-y-4">
        <TabsList className="grid grid-cols-3 max-w-md">
          <TabsTrigger value="schedule"><CalendarDays className="h-3.5 w-3.5 mr-1" />Schedule</TabsTrigger>
          <TabsTrigger value="types"><FileText className="h-3.5 w-3.5 mr-1" />Exam Types</TabsTrigger>
          <TabsTrigger value="report"><Trophy className="h-3.5 w-3.5 mr-1" />Detailed Report</TabsTrigger>
        </TabsList>

        <TabsContent value="schedule" className="space-y-4">
          <Card className="border-border/60">
            <CardHeader className="pb-2">
              <CardTitle className="font-display text-base">Upcoming Exam Schedule</CardTitle>
              <CardDescription>{upcoming.length} exam series scheduled for your class</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              {upcoming.map((e) => (
                <div key={e.id} className="border rounded-lg p-4 hover:bg-muted/30 transition">
                  <div className="flex items-start justify-between gap-3 flex-wrap mb-3">
                    <div>
                      <div className="text-sm font-semibold">{e.name}</div>
                      <div className="text-xs text-muted-foreground flex items-center gap-3 mt-1">
                        <span className="flex items-center gap-1"><CalendarDays className="h-3 w-3" />{formatExamDate(e.from)} – {formatExamDate(e.to)}</span>
                        <span className="flex items-center gap-1"><BookOpen className="h-3 w-3" />{e.subjects} subjects</span>
                        <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />Class {e.class}</span>
                      </div>
                    </div>
                    <Badge variant="outline" className="bg-primary/10 text-primary border-primary/20">{e.status}</Badge>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 mt-3">
                    {(e.papers ?? []).map((paper) => (
                      <div key={paper.paper_uuid} className="border rounded-md p-2.5 text-xs bg-muted/20">
                        <div className="font-medium text-sm">{paper.subject_name ?? paper.paper_name}</div>
                        <div className="text-muted-foreground flex items-center gap-1 mt-0.5"><Clock className="h-3 w-3" />{formatExamDate(paper.date)} · {formatExamTime(paper.time)}{paper.duration_minutes ? ` (${paper.duration_minutes} min)` : ""}</div>
                        <div className="text-muted-foreground flex items-center gap-1"><MapPin className="h-3 w-3" />{paper.room_name ? `Room ${paper.room_name}` : "Room TBD"}</div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              {upcoming.length === 0 && <div className="text-xs text-muted-foreground text-center p-8">No upcoming exams.</div>}
            </CardContent>
          </Card>

          {completed.length > 0 && <Card className="border-border/60">
            <CardHeader className="pb-2"><CardTitle className="font-display text-base">Past Exams</CardTitle></CardHeader>
            <CardContent className="p-0 overflow-x-auto">
              <Table>
                <TableHeader><TableRow><TableHead>Exam</TableHead><TableHead>Period</TableHead><TableHead>Subjects</TableHead><TableHead>Status</TableHead><TableHead>Result</TableHead></TableRow></TableHeader>
                <TableBody>
                  {completed.map((e) => (
                    <TableRow key={e.id}>
                      <TableCell className="text-sm font-medium">{e.name}</TableCell>
                      <TableCell className="text-xs text-muted-foreground">{e.from} – {e.to}</TableCell>
                      <TableCell className="text-xs">{e.subjects}</TableCell>
                      <TableCell><Badge variant="secondary" className="text-[10px]">{e.status}</Badge></TableCell>
                      <TableCell><Button variant="ghost" size="sm" asChild><Link to="/student/results">View</Link></Button></TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>}
        </TabsContent>

        <TabsContent value="types" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {(portalTypes.length ? portalTypes : EXAM_TYPES).map((t) => (
              <Card key={t.type} className="border-border/60">
                <CardHeader className="pb-2 flex-row items-center justify-between space-y-0">
                  <CardTitle className="font-display text-base flex items-center gap-2"><Award className="h-4 w-4" />{t.type}</CardTitle>
                  <Badge variant="outline" className={t.color}>{t.weight}</Badge>
                </CardHeader>
                <CardContent className="space-y-2">
                  <div className="text-xs text-muted-foreground">{t.description}</div>
                  <div className="flex items-center justify-between text-xs pt-2 border-t">
                    <span className="text-muted-foreground">Per academic year</span>
                    <span className="font-semibold">{t.count} {t.count > 1 ? "exams" : "exam"}</span>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          <Card className="border-border/60">
            <CardHeader className="pb-2"><CardTitle className="font-display text-base">Grading Scale (CBSE)</CardTitle></CardHeader>
            <CardContent className="p-0 overflow-x-auto">
              <Table>
                <TableHeader><TableRow><TableHead>Grade</TableHead><TableHead>Marks Range</TableHead><TableHead>GPA</TableHead><TableHead>Remarks</TableHead></TableRow></TableHeader>
                <TableBody>
                  {[
                    ["A1", "91 – 100", "10", "Outstanding"],
                    ["A2", "81 – 90", "9", "Excellent"],
                    ["B1", "71 – 80", "8", "Very Good"],
                    ["B2", "61 – 70", "7", "Good"],
                    ["C1", "51 – 60", "6", "Above Average"],
                    ["C2", "41 – 50", "5", "Average"],
                    ["D", "33 – 40", "4", "Pass"],
                  ].map((r) => (
                    <TableRow key={r[0]}>
                      <TableCell><Badge variant="secondary" className="font-mono">{r[0]}</Badge></TableCell>
                      <TableCell className="text-sm">{r[1]}</TableCell>
                      <TableCell className="text-sm font-semibold">{r[2]}</TableCell>
                      <TableCell className="text-xs text-muted-foreground">{r[3]}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="report" className="space-y-4">
          <Card className="border-border/60">
            <CardHeader className="pb-2 flex-row items-start justify-between gap-2 flex-wrap space-y-0">
              <div>
                <CardTitle className="font-display text-base">Detailed Exam Report</CardTitle>
                <CardDescription>Subject-wise performance, grade and rank analysis</CardDescription>
              </div>
              <div className="flex items-center gap-2">
                <Select value={selectedExam} onValueChange={setSelectedExam}>
                  <SelectTrigger className="h-9 w-56"><SelectValue /></SelectTrigger>
                  <SelectContent>{examIds.map((id) => <SelectItem key={id} value={id}>{myMarks.find((mark) => mark.examId === id)?.examName ?? id}</SelectItem>)}</SelectContent>
                </Select>
                <Button size="sm" variant="outline" onClick={() => toast.success("Report card PDF downloaded")}><Download className="h-4 w-4" />PDF</Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
                <div className="border rounded-md p-3"><div className="text-[10px] text-muted-foreground uppercase">Total</div><div className="text-lg font-display font-bold">{totalObt}/{totalMax}</div></div>
                <div className="border rounded-md p-3"><div className="text-[10px] text-muted-foreground uppercase">Percentage</div><div className="text-lg font-display font-bold text-primary">{pct}%</div></div>
                <div className="border rounded-md p-3"><div className="text-[10px] text-muted-foreground uppercase">Grade</div><div className="text-lg font-display font-bold text-success">{grade(pct)}</div></div>
                <div className="border rounded-md p-3"><div className="text-[10px] text-muted-foreground uppercase">GPA</div><div className="text-lg font-display font-bold">{gpa(pct)}/10</div></div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-4">
                <div className="border rounded-md p-3">
                  <div className="text-xs font-medium mb-2 flex items-center gap-1"><Target className="h-3.5 w-3.5" />Subject Scores</div>
                  <ResponsiveContainer width="100%" height={220}>
                    <BarChart data={barData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
                      <XAxis dataKey="subject" fontSize={10} stroke="var(--muted-foreground)" />
                      <YAxis fontSize={10} stroke="var(--muted-foreground)" />
                      <Tooltip contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, fontSize: 12 }} />
                      <Legend iconSize={8} wrapperStyle={{ fontSize: 10 }} />
                      <Bar dataKey="obtained" name="Obtained" fill="var(--chart-1)" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="max" name="Max" fill="var(--chart-3)" radius={[4, 4, 0, 0]} opacity={0.4} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <div className="border rounded-md p-3">
                  <div className="text-xs font-medium mb-2 flex items-center gap-1"><TrendingUp className="h-3.5 w-3.5" />Strength Radar</div>
                  <ResponsiveContainer width="100%" height={220}>
                    <RadarChart data={radarData}>
                      <PolarGrid stroke="var(--border)" />
                      <PolarAngleAxis dataKey="subject" fontSize={10} stroke="var(--muted-foreground)" />
                      <PolarRadiusAxis fontSize={9} stroke="var(--muted-foreground)" />
                      <Radar dataKey="score" stroke="var(--chart-1)" fill="var(--chart-1)" fillOpacity={0.4} />
                    </RadarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="overflow-x-auto">
                <Table>
                  <TableHeader><TableRow><TableHead>Subject</TableHead><TableHead className="text-right">Max</TableHead><TableHead className="text-right">Obtained</TableHead><TableHead>Progress</TableHead><TableHead>Grade</TableHead><TableHead>Remark</TableHead></TableRow></TableHeader>
                  <TableBody>
                    {examRows.map((m) => {
                      const p = Math.round(((m.obtained ?? 0) / m.max) * 100);
                      return (
                        <TableRow key={m.id}>
                          <TableCell className="text-sm font-medium">{m.subject}</TableCell>
                          <TableCell className="text-right text-xs text-muted-foreground">{m.max}</TableCell>
                          <TableCell className="text-right text-sm font-semibold">{m.obtained ?? "—"}</TableCell>
                          <TableCell className="w-40"><Progress value={p} className="h-2" /></TableCell>
                          <TableCell><Badge variant="secondary" className="font-mono">{grade(p)}</Badge></TableCell>
                          <TableCell className="text-xs text-muted-foreground">{p >= 75 ? "Excellent" : p >= 60 ? "Good" : p >= 40 ? "Needs work" : "Improvement needed"}</TableCell>
                        </TableRow>
                      );
                    })}
                    {examRows.length === 0 && <TableRow><TableCell colSpan={6} className="text-center text-xs text-muted-foreground py-6">No published marks for this exam yet.</TableCell></TableRow>}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </PageContainer>
  );
}

import { useEffect, useMemo, useState } from "react";
import { BookOpenCheck, Download, ExternalLink, FileBox, Loader2, Search } from "lucide-react";
import { toast } from "sonner";
import studentModel from "../../api/studentModel";
import { PageContainer, PageHeader } from "../../components/page-shell";
import { Badge } from "../../components/ui/badge";
import { Button } from "../../components/ui/button";
import { Card, CardContent } from "../../components/ui/card";
import { Input } from "../../components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../../components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../components/ui/tabs";

const errorMessage = (error, fallback = "Unable to load study content.") => error?.response?.data?.detail?.message || error?.response?.data?.detail || error?.response?.data?.message || error?.message || fallback;
const openUrl = (url) => window.open(url, "_blank", "noopener,noreferrer");

export default function StudyMaterials() {
  const [materials, setMaterials] = useState([]);
  const [lessonPlans, setLessonPlans] = useState([]);
  const [loading, setLoading] = useState(true);
  const [downloadingUuid, setDownloadingUuid] = useState(null);
  const [q, setQ] = useState("");
  const [subject, setSubject] = useState("all");

  useEffect(() => {
    Promise.allSettled([studentModel.getMyMaterials(), studentModel.getMyLessonPlans()]).then(([materialsResult, lessonsResult]) => {
      if (materialsResult.status === "fulfilled") setMaterials(materialsResult.value?.data || []);
      else toast.error(errorMessage(materialsResult.reason, "Unable to load study materials."));
      if (lessonsResult.status === "fulfilled") setLessonPlans(lessonsResult.value?.data || []);
      else toast.error(errorMessage(lessonsResult.reason, "Unable to load lesson plans."));
    }).finally(() => setLoading(false));
  }, []);

  const subjects = useMemo(() => [...new Set([...materials, ...lessonPlans].map((item) => item.subject_name).filter(Boolean))], [materials, lessonPlans]);
  const matches = (item) => {
    const query = q.trim().toLowerCase();
    return (subject === "all" || item.subject_name === subject) && (!query || [item.title, item.description, item.file_name, item.subject_name, item.chapter, item.topic, item.learning_objectives].some((field) => field?.toLowerCase().includes(query)));
  };
  const visibleMaterials = useMemo(() => materials.filter(matches), [materials, q, subject]);
  const visibleLessons = useMemo(() => lessonPlans.filter(matches), [lessonPlans, q, subject]);
  const classLabel = materials[0]?.class_name || lessonPlans[0]?.class_name;

  const download = async (uuid, getUrl) => {
    setDownloadingUuid(uuid);
    try {
      const response = await getUrl(uuid);
      const url = response?.data?.download_url;
      if (!url) throw new Error("No download URL was returned.");
      openUrl(url);
      toast.success("Download opened.");
    } catch (error) {
      toast.error(errorMessage(error, "Unable to open the download."));
    } finally {
      setDownloadingUuid(null);
    }
  };

  return <PageContainer>
    <PageHeader eyebrow="Student Portal" title="Study Materials" description={classLabel ? `Resources and lesson plans mapped to ${classLabel}` : "Resources and lesson plans mapped to your class"} />
    <div className="flex gap-2 mb-3"><div className="relative flex-1 max-w-sm"><Search className="h-4 w-4 absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" /><Input className="pl-8 h-9" placeholder="Search…" value={q} onChange={(event) => setQ(event.target.value)} /></div><Select value={subject} onValueChange={setSubject}><SelectTrigger className="h-9 w-44"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All subjects</SelectItem>{subjects.map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div>
    <Tabs defaultValue="materials"><TabsList><TabsTrigger value="materials">Materials ({materials.length})</TabsTrigger><TabsTrigger value="lessons">Lesson Plans ({lessonPlans.length})</TabsTrigger></TabsList>
      <TabsContent value="materials"><Card><CardContent className="p-0 divide-y">{loading && <Loading label="Loading materials…" />}{!loading && visibleMaterials.map((material) => <div key={material.material_uuid} className="flex items-start gap-3 p-3 hover:bg-muted/40"><Icon icon={<FileBox className="h-4 w-4" />} /><div className="flex-1 min-w-0"><div className="text-sm font-medium truncate">{material.title}</div><div className="text-[11px] text-muted-foreground">{material.subject_name || "—"} · {material.type || "File"}{material.file_name && ` · ${material.file_name}`}</div>{material.description && <div className="text-[11px] mt-1 text-muted-foreground">{material.description}</div>}</div><Button size="sm" variant="outline" disabled={downloadingUuid === material.material_uuid} onClick={() => download(material.material_uuid, studentModel.getMaterialDownloadUrl)}><DownloadIcon loading={downloadingUuid === material.material_uuid} />Download</Button><Badge variant="outline" className="text-[10px]">{material.downloads ?? 0}</Badge></div>)}{!loading && visibleMaterials.length === 0 && <Empty label="No materials match your filters." />}</CardContent></Card></TabsContent>
      <TabsContent value="lessons"><Card><CardContent className="p-0 divide-y">{loading && <Loading label="Loading lesson plans…" />}{!loading && visibleLessons.map((lesson) => <div key={lesson.lesson_plan_uuid} className="flex items-start gap-3 p-3 hover:bg-muted/40"><Icon icon={<BookOpenCheck className="h-4 w-4" />} /><div className="flex-1 min-w-0"><div className="text-sm font-medium">{lesson.title}</div><div className="text-[11px] text-muted-foreground">{lesson.subject_name || "—"} · {lesson.chapter || "—"}{lesson.topic && ` · ${lesson.topic}`}</div><div className="text-[11px] mt-1 text-muted-foreground">Week of {lesson.week_of || "—"} · {lesson.periods ?? 0} periods</div>{lesson.learning_objectives && <div className="text-xs mt-1">{lesson.learning_objectives}</div>}</div>{lesson.reference_url && <Button size="sm" variant="ghost" onClick={() => openUrl(lesson.reference_url)}><ExternalLink className="h-3.5 w-3.5" />Reference</Button>}{lesson.pdf_file_name && <Button size="sm" variant="outline" disabled={downloadingUuid === lesson.lesson_plan_uuid} onClick={() => download(lesson.lesson_plan_uuid, studentModel.getLessonPlanDownloadUrl)}><DownloadIcon loading={downloadingUuid === lesson.lesson_plan_uuid} />PDF</Button>}</div>)}{!loading && visibleLessons.length === 0 && <Empty label="No lesson plans match your filters." />}</CardContent></Card></TabsContent>
    </Tabs>
  </PageContainer>;
}

function Icon({ icon }) { return <div className="h-9 w-9 rounded-md flex items-center justify-center bg-info/10 text-info shrink-0">{icon}</div>; }
function Loading({ label }) { return <div className="text-sm text-muted-foreground text-center p-6"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />{label}</div>; }
function Empty({ label }) { return <div className="text-sm text-muted-foreground text-center p-6">{label}</div>; }
function DownloadIcon({ loading }) { return loading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />; }

import { PageContainer, PageHeader } from "../../components/page-shell";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "../../components/ui/card";
import { Badge } from "../../components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../components/ui/table";
import { Button } from "../../components/ui/button";
import {
  MapPin,
  RefreshCw,
  Fuel,
  Gauge,
  Bus,
  Navigation,
  ParkingCircle,
  Route as RouteIcon,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { getVecvVehicles, syncVecvLiveData } from "../../api/transport";

// Cache reverse-geocoding results across renders/mounts (module-level, in-memory)
const geocodeCache = new Map();

export default function StudentTransport() {
  const [vehicles, setVehicles] = useState([]);
  const [loadingVehicles, setLoadingVehicles] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [lastSyncedAt, setLastSyncedAt] = useState(null);
  const [retryAfterSeconds, setRetryAfterSeconds] = useState(0);

  const [placeNames, setPlaceNames] = useState({});
  const [resolvingKeys, setResolvingKeys] = useState(new Set());

  // --- Retry countdown for rate-limited GPS sync ---
  useEffect(() => {
    if (!retryAfterSeconds) return undefined;
    const timer = window.setInterval(() => {
      setRetryAfterSeconds((seconds) => Math.max(0, seconds - 1));
    }, 1000);
    return () => window.clearInterval(timer);
  }, [retryAfterSeconds]);

  // --- Load saved vehicle GPS data ---
  const loadSavedVehicles = useCallback(async () => {
    setLoadingVehicles(true);
    try {
      const response = await getVecvVehicles();
      const payload = response?.data?.data ?? response?.data ?? {};
      const list = Array.isArray(payload) ? payload : payload.vehicleData ?? payload.vehicles ?? [];
      setVehicles(list.filter((v) => v && v.vehicleNo));
      setLastSyncedAt(payload.lastSyncedAt ?? payload.last_synced_at ?? null);
    } catch (error) {
      if (error?.response?.status !== 404) {
        toast.error(error?.response?.data?.message ?? "Unable to load saved vehicle locations");
      }
      setVehicles([]);
    } finally {
      setLoadingVehicles(false);
    }
  }, []);

  useEffect(() => {
    loadSavedVehicles();
  }, [loadSavedVehicles]);

  // --- Reverse-geocode vehicle coordinates into place names ---
  useEffect(() => {
    if (!vehicles.length) return;

    vehicles.forEach((vehicle) => {
      const { latitude, longitude } = vehicle;
      if (latitude === null || latitude === undefined || longitude === null || longitude === undefined) return;
      if (Number(latitude) === 0 && Number(longitude) === 0) return;

      const key = `${Number(latitude).toFixed(5)},${Number(longitude).toFixed(5)}`;

      if (geocodeCache.has(key)) {
        setPlaceNames((prev) => (prev[key] ? prev : { ...prev, [key]: geocodeCache.get(key) }));
        return;
      }
      if (resolvingKeys.has(key)) return;

      setResolvingKeys((prev) => new Set(prev).add(key));

      fetch(
        `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}&zoom=16&addressdetails=1`,
        { headers: { Accept: "application/json" } }
      )
        .then((res) => (res.ok ? res.json() : Promise.reject(res.status)))
        .then((data) => {
          const addr = data?.address ?? {};
          const name =
            addr.road ||
            addr.neighbourhood ||
            addr.suburb ||
            addr.village ||
            addr.town ||
            addr.city_district ||
            addr.city ||
            data?.display_name?.split(",").slice(0, 2).join(",").trim() ||
            "Unknown location";

          geocodeCache.set(key, name);
          setPlaceNames((prev) => ({ ...prev, [key]: name }));
        })
        .catch(() => {
          geocodeCache.set(key, null);
          setPlaceNames((prev) => ({ ...prev, [key]: null }));
        })
        .finally(() => {
          setResolvingKeys((prev) => {
            const next = new Set(prev);
            next.delete(key);
            return next;
          });
        });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vehicles]);

  const syncLiveGps = async () => {
    if (retryAfterSeconds > 0) return;

    setSyncing(true);
    try {
      const response = await syncVecvLiveData();
      const payload = response?.data?.data ?? response?.data ?? {};
      const list = payload.vehicleData ?? [];
      setVehicles(list.filter((v) => v && v.vehicleNo));
      setLastSyncedAt(payload.lastSyncedAt ?? null);
      setRetryAfterSeconds(0);
      toast.success(payload.cached ? "Showing cached vehicle data" : "Live GPS data synced");
    } catch (error) {
      const detail = error?.response?.data?.detail;
      const retryAfter = Number(detail?.retryAfterSeconds ?? 0);

      if (error?.response?.status === 429 && retryAfter > 0) {
        setRetryAfterSeconds(retryAfter);
        toast.error(`${detail.message} Try again in ${retryAfter} seconds.`);
      } else {
        toast.error(detail?.message ?? error?.response?.data?.message ?? "Unable to sync live GPS data");
      }
    } finally {
      setSyncing(false);
    }
  };

  // --- Derived summary stats from real vehicle data (no hardcoding) ---
  const stats = useMemo(() => {
    const total = vehicles.length;
    const moving = vehicles.filter((v) => v.deviceStatus === "MOVING").length;
    const stopped = vehicles.filter((v) => v.deviceStatus === "STOPPED").length;
    const fuelValues = vehicles
      .map((v) => v.fuelLevelInPer)
      .filter((val) => val !== null && val !== undefined);
    const avgFuel = fuelValues.length
      ? Math.round(fuelValues.reduce((a, b) => a + b, 0) / fuelValues.length)
      : null;
    return { total, moving, stopped, avgFuel };
  }, [vehicles]);

  return (
    <PageContainer>
      <PageHeader
        eyebrow="Student Portal"
        title="Bus Tracking"
        description="Live and last-known GPS positions for campus buses."
      />

      {/* Summary stat strip */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <StatCard
          icon={<Bus className="h-4 w-4" />}
          label="Total Buses"
          value={loadingVehicles ? "—" : stats.total}
          accent="bg-primary/10 text-primary"
        />
        <StatCard
          icon={<Navigation className="h-4 w-4" />}
          label="Moving"
          value={loadingVehicles ? "—" : stats.moving}
          accent="bg-emerald-500/10 text-emerald-600"
        />
        <StatCard
          icon={<ParkingCircle className="h-4 w-4" />}
          label="Stopped"
          value={loadingVehicles ? "—" : stats.stopped}
          accent="bg-slate-500/10 text-slate-600"
        />
        <StatCard
          icon={<Fuel className="h-4 w-4" />}
          label="Avg. Fuel"
          value={loadingVehicles || stats.avgFuel === null ? "—" : `${stats.avgFuel}%`}
          accent="bg-amber-500/10 text-amber-600"
        />
      </div>

      <Card className="border-border/60 shadow-sm overflow-hidden">
        <CardHeader className="pb-4 flex-row items-center justify-between space-y-0 gap-3 bg-gradient-to-r from-muted/40 to-transparent">
          <div>
            <CardTitle className="font-display text-lg tracking-tight">Live Bus Locations</CardTitle>
            <CardDescription className="mt-1">
              {lastSyncedAt ? (
                <span className="inline-flex items-center gap-1.5">
                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
                  Last synced {formatDateTime(lastSyncedAt)}
                </span>
              ) : (
                "Saved positions from VECV"
              )}
            </CardDescription>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={syncLiveGps}
            disabled={syncing || retryAfterSeconds > 0}
            className="shadow-sm"
          >
            <RefreshCw className={`h-4 w-4 ${syncing ? "animate-spin" : ""}`} />
            {syncing ? "Syncing" : retryAfterSeconds > 0 ? `Try again in ${retryAfterSeconds}s` : "Sync live GPS"}
          </Button>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent border-border/60">
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Route</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Vehicle</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Model</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Engine No.</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Chassis No.</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Status</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Speed</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Location</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Fuel</TableHead>
                <TableHead className="text-[11px] uppercase tracking-wide text-muted-foreground">Odometer</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {!loadingVehicles && vehicles.map((vehicle) => {
                const isMoving = vehicle.deviceStatus === "MOVING";
                return (
                  <TableRow
                    key={vehicle.deviceId ?? vehicle.vehicleNo}
                    className="border-border/60 transition-colors hover:bg-muted/40"
                  >
                    <TableCell className="text-xs font-medium">
                      {vehicle.route ? (
                        <span className="inline-flex items-center gap-1.5">
                          <RouteIcon className="h-3 w-3 text-primary" />
                          {vehicle.route}
                        </span>
                      ) : (
                        <span className="text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className="h-7 w-7 rounded-lg bg-primary/10 text-primary flex items-center justify-center shrink-0">
                          <Bus className="h-3.5 w-3.5" />
                        </div>
                        <span className="font-mono text-xs font-medium">{vehicle.vehicleNo ?? "—"}</span>
                      </div>
                    </TableCell>
                    <TableCell className="text-xs">{vehicle.model ?? "—"}</TableCell>
                    <TableCell className="font-mono text-[11px] text-muted-foreground">
                      {vehicle.engineNo ?? "—"}
                    </TableCell>
                    <TableCell className="font-mono text-[11px] text-muted-foreground">
                      {vehicle.chassisNo ?? "—"}
                    </TableCell>
                    <TableCell>
                      <span
                        className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium ${
                          isMoving
                            ? "bg-emerald-500/10 text-emerald-700"
                            : vehicle.deviceStatus === "STOPPED"
                            ? "bg-slate-500/10 text-slate-600"
                            : "bg-muted text-muted-foreground"
                        }`}
                      >
                        <span
                          className={`h-1.5 w-1.5 rounded-full ${
                            isMoving ? "bg-emerald-500 animate-pulse" : "bg-slate-400"
                          }`}
                        />
                        {vehicle.deviceStatus ?? "Unknown"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="flex items-center gap-1.5 text-sm font-medium">
                        <Gauge className="h-3.5 w-3.5 text-muted-foreground" />
                        {vehicle.vehicleSpeed ?? 0}
                        <span className="text-muted-foreground text-xs font-normal">km/h</span>
                      </span>
                    </TableCell>
                    <TableCell className="text-xs max-w-[180px]">
                      <span className="flex items-center gap-1.5">
                        <MapPin className="h-3.5 w-3.5 text-primary shrink-0" />
                        <span className="truncate">{resolveLocationLabel(vehicle, placeNames, resolvingKeys)}</span>
                      </span>
                    </TableCell>
                    <TableCell className="text-xs">
                      <FuelBar value={vehicle.fuelLevelInPer} />
                    </TableCell>
                    <TableCell className="text-sm font-medium tabular-nums">
                      {vehicle.odometer !== undefined && vehicle.odometer !== null
                        ? `${Number(vehicle.odometer).toLocaleString()} km`
                        : "—"}
                    </TableCell>
                  </TableRow>
                );
              })}
              {(loadingVehicles || !vehicles.length) && (
                <TableRow>
                  <TableCell colSpan={10} className="py-12 text-center">
                    <div className="flex flex-col items-center gap-2 text-muted-foreground">
                      <Bus className="h-8 w-8 opacity-30" />
                      <span className="text-sm">
                        {loadingVehicles
                          ? "Loading saved vehicle locations…"
                          : "No saved GPS data. Sync live GPS to get the latest locations."}
                      </span>
                    </div>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </PageContainer>
  );
}

function StatCard({ icon, label, value, accent }) {
  return (
    <Card className="border-border/60 shadow-sm">
      <CardContent className="p-4 flex items-center gap-3">
        <div className={`h-10 w-10 rounded-xl flex items-center justify-center shrink-0 ${accent}`}>
          {icon}
        </div>
        <div className="min-w-0">
          <div className="text-[11px] uppercase tracking-wide text-muted-foreground">{label}</div>
          <div className="text-xl font-semibold tabular-nums">{value}</div>
        </div>
      </CardContent>
    </Card>
  );
}

function FuelBar({ value }) {
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground">—</span>;
  }
  const pct = Math.max(0, Math.min(100, Number(value)));
  const barColor = pct > 50 ? "bg-emerald-500" : pct > 20 ? "bg-amber-500" : "bg-red-500";
  return (
    <div className="flex items-center gap-2 w-24">
      <div className="h-1.5 flex-1 rounded-full bg-muted overflow-hidden">
        <div className={`h-full rounded-full ${barColor}`} style={{ width: `${pct}%` }} />
      </div>
      <span className="text-[11px] font-medium tabular-nums w-9 text-right">{pct}%</span>
    </div>
  );
}

function resolveLocationLabel(vehicle, placeNames, resolvingKeys) {
  const { latitude, longitude } = vehicle;
  if (latitude === null || latitude === undefined || longitude === null || longitude === undefined) return "—";
  if (Number(latitude) === 0 && Number(longitude) === 0) return "—";

  const key = `${Number(latitude).toFixed(5)},${Number(longitude).toFixed(5)}`;
  const resolved = placeNames[key];

  if (resolved) return resolved;
  if (resolvingKeys.has(key)) return "Locating…";
  return `${Number(latitude).toFixed(4)}, ${Number(longitude).toFixed(4)}`;
}

function formatDateTime(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleString();
}

