// The backend expects upper-case enum values for category/audience; the form
// dropdowns use the human-friendly labels above, so map between the two here.
const CATEGORY_MAP = {
  Academic: "ACADEMIC",
  Events: "EVENTS",
  Fees: "FEES",
  Holiday: "HOLIDAY",
  Exam: "EXAM",
  General: "GENERAL",
};

const AUDIENCE_MAP = {
  All: "ALL",
  Teachers: "TEACHERS",
  Students: "STUDENTS",
  Parents: "PARENTS",
  Staff: "STAFF",
  Class: "CLASS",
};

const CATEGORY_REVERSE_MAP = Object.fromEntries(
  Object.entries(CATEGORY_MAP).map(([label, value]) => [value, label])
);

const AUDIENCE_REVERSE_MAP = Object.fromEntries(
  Object.entries(AUDIENCE_MAP).map(([label, value]) => [value, label])
);

// List endpoints in different deployments return either `data: []` or
// `data: { data: [] }`. Keep the audience dropdowns resilient to both.
const getResponseList = (response) => {
  if (Array.isArray(response)) return response;
  if (Array.isArray(response?.data)) return response.data;
  if (Array.isArray(response?.data?.data)) return response.data.data;
  return [];
};

// The /communications router validates with Pydantic, so a bad value comes
// back as a 422 with `detail` as a LIST of {loc, msg, type} objects rather
// than a plain string. The previous version only handled the string/object
// shape, so validation failures (e.g. a missing/invalid category_uuid) fell
// through to the generic fallback message and hid the real reason. Handle
// all three shapes FastAPI can send.
const getApiErrorMessage = (error, fallback) => {
  const detail = error?.response?.data?.detail;

  if (Array.isArray(detail)) {
    const messages = detail
      .map((item) => item?.msg)
      .filter(Boolean);
    if (messages.length > 0) return messages.join(" ");
  }

  const payload = detail && typeof detail === "object" && !Array.isArray(detail) ? detail : error?.response?.data;

  if (typeof detail === "string") return detail;
  if (typeof payload === "string") return payload;
  if (typeof payload?.message === "string") return payload.message;
  if (typeof error?.message === "string") return error.message;
  return fallback;
};
const buildNoticeFormData = ({
  title,
  body,
  category,
  audience,
  classUUID,
  sectionUUID,
  startDate,
  endDate,
  attachments = [],
  existingAttachments = [],
}) => {
  const formData = new FormData();
  formData.append("title", title);
  formData.append("description", body);
  formData.append("category", CATEGORY_MAP[category] ?? category);
  formData.append("audience_type", AUDIENCE_MAP[audience] ?? audience);
  if (audience === "Class") {
    if (classUUID) {
      // The publish/save-draft API accepts one multipart `class_audiences`
      // field containing a JSON array of class/section audience objects.
      formData.append(
        "class_audiences",
        JSON.stringify([
          {
            class_uuid: classUUID,
            ...(sectionUUID ? { section_uuids: [sectionUUID] } : {}),
          },
        ])
      );
    }
  }
  formData.append("start_date", startDate);
  formData.append("end_date", endDate);

  // Swagger defines a single optional UploadFile named `attachment`.
  if (attachments[0]) {
    formData.append("attachment", attachments[0]);
  }

  existingAttachments.forEach((att) => {
    if (att.uuid ?? att.id) {
      formData.append("keep_attachment_uuids", att.uuid ?? att.id);
    }
  });

  return formData;
};

// Matches NoteCreateRequest / NoteUpdateRequest.as_form on the backend
// exactly: category_uuid, title, start_date, end_date, description,
// audience (upper-case enum), plus the separate `attachments` file list
// parameter the router reads independently of the payload model. `status`
// is intentionally NOT sent here — the router forces it to DRAFT/PUBLISHED
// for the save-draft/publish endpoints, and NoteUpdateRequest treats a
// missing field as "leave unchanged" for plain updates.
const buildCommunicationNoteFormData = ({
  title,
  body,
  categoryUUID,
  audience,
  startDate,
  endDate,
  attachments = [],
}) => {
  const formData = new FormData();
  formData.append("title", title);
  formData.append("description", body);
  formData.append("category_uuid", categoryUUID);
  formData.append("audience", AUDIENCE_MAP[audience] ?? audience);
  formData.append("start_date", startDate);
  formData.append("end_date", endDate);
  attachments.forEach((attachment) => formData.append("attachments", attachment));
  return formData;
};

const buildHolidayFormData = ({
  title, body, category, audience, classUUID, sectionUUID,
  startDate, endDate, attachments = [], existingAttachments = [],
}) => {
  const formData = new FormData();
  formData.append("title", title);
  formData.append("description", body);
  formData.append("category", CATEGORY_MAP[category] ?? category ?? "HOLIDAY");
  formData.append("audience_type", AUDIENCE_MAP[audience] ?? audience);
  if (audience === "Class" && classUUID) {
    // Backend's HolidayCalendarDraftRequest.as_form reads class_uuid and
    // section_uuids as direct form fields (not a class_audiences JSON blob).
    formData.append("class_uuid", classUUID);
    if (sectionUUID) {
      formData.append("section_uuids", sectionUUID);
    }
  }
  formData.append("start_date", startDate);
  formData.append("end_date", endDate);
  if (attachments[0]) formData.append("attachment", attachments[0]);
  existingAttachments.forEach((att) => {
    if (att.uuid ?? att.id) formData.append("keep_attachment_uuids", att.uuid ?? att.id);
  });
  return formData;
};

const buildAcademicCalendarFormData = ({
  title,
  body,
  category,
  audience,
  classUUID,
  sectionUUID,
  startDate,
  endDate,
  attachments = [],
  existingAttachmentUUID,
}) => {
  const formData = new FormData();
  formData.append("title", title);
  formData.append("description", body);
  formData.append("category", CATEGORY_MAP[category] ?? category ?? "ACADEMIC");
  formData.append("audience_type", AUDIENCE_MAP[audience] ?? audience ?? "ALL");
  if (audience === "Class" && classUUID) {
    // The calendar API has used both the direct UUID fields and the audience
    // collection across deployments. Send the direct values as well so they
    // are persisted and returned when this entry is opened for editing.
    formData.append("class_uuid", classUUID);
    if (sectionUUID) formData.append("section_uuid", sectionUUID);
    formData.append(
      "class_audiences",
      JSON.stringify([
        {
          class_uuid: classUUID,
          ...(sectionUUID ? { section_uuids: [sectionUUID] } : {}),
        },
      ])
    );
  }
  formData.append("start_date", startDate);
  formData.append("end_date", endDate);
  if (attachments[0]) formData.append("attachment", attachments[0]);
  if (existingAttachmentUUID) {
    formData.append("keep_attachment_uuid", existingAttachmentUUID);
  }
  return formData;
};


