                          <div
                            key={`${file.name}-${idx}`}
                            className="flex items-center justify-between rounded-md border px-2 py-1 text-xs bg-muted/20"
                          >
                            <div className="flex items-center gap-1.5 min-w-0">
                              {previewUrl && kind === "image" ? (
                                <img
                                  src={previewUrl}
                                  alt={file.name}
                                  className="h-6 w-6 rounded object-cover shrink-0"
                                />
                              ) : previewUrl && kind === "video" ? (
                                <video src={previewUrl} className="h-6 w-6 rounded object-cover shrink-0" muted />
                              ) : (
                                attachmentIcon(file)
                              )}
                              <span className="truncate max-w-[180px]">
                                {file.name}
                              </span>
                              <span className="text-muted-foreground shrink-0">
                                ({formatSize(file.size)})
                              </span>
                            </div>
                            <div className="flex items-center gap-1 shrink-0">
                              {previewUrl && (
                                <button
                                  type="button"
                                  title={`View ${file.name}`}
                                  onClick={() =>
                                    openAttachmentPreview({ name: file.name, type: file.type, url: previewUrl })
                                  }
                                  className="text-muted-foreground hover:text-foreground p-0.5 rounded hover:bg-muted"
                                >
                                  <Eye className="h-3.5 w-3.5" />
                                </button>
                              )}
                              <button
                                type="button"
                                onClick={() => removeAttachment(idx)}
                                className="text-muted-foreground hover:text-foreground p-0.5 rounded hover:bg-muted"
                              >
                                <X className="h-3.5 w-3.5" />
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
              )}
              <DialogFooter>

  <Button

    variant="outline"

    onClick={() => submit(false)}

    disabled={savingCurrent}

  >

    {savingCurrent ? <Loader2 className="h-4 w-4 animate-spin" /> : null}

    Save Draft

  </Button>

  <Button

    className="gradient-primary border-0"

    onClick={() => submit(true)}

    disabled={savingCurrent}

  >

    {savingCurrent ? (

      <Loader2 className="h-4 w-4 animate-spin" />

    ) : (

      <Send className="h-4 w-4" />

    )}

    {editingCalendarUUID || editingNoticeUUID || editingEventUUID || editingHolidayUUID

      ? "Save Changes"

      : "Publish"}

  </Button>

</DialogFooter>
            </DialogContent>
          </Dialog>
        }
      />
      <Tabs value={workspaceTab} onValueChange={setWorkspaceTab} className="mb-4">
        <TabsList>
          <TabsTrigger value="categories">Categories</TabsTrigger>
          <TabsTrigger value="communications">Communications</TabsTrigger>
        </TabsList>
      </Tabs>

      {workspaceTab === "categories" && (
        <Card>
          <CardContent className="space-y-4 p-5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h2 className="font-semibold">Communication Categories</h2>
                <p className="text-sm text-muted-foreground">Add, rename, or remove communication categories.</p>
              </div>
              <Popover open={addingCategory} onOpenChange={setAddingCategory}>
                <PopoverTrigger asChild>
                  <Button type="button" size="sm"><Plus className="mr-1.5 h-4 w-4" />Add Category</Button>
                </PopoverTrigger>
                <PopoverContent className="w-64 p-3" align="end">
                  <div className="flex flex-col gap-2">
                    <Label>Category name</Label>
                    <Input value={newCategoryName} onChange={(event) => setNewCategoryName(event.target.value)} placeholder="e.g. Academic" />
                    <Button type="button" size="sm" onClick={handleCreateCategory} disabled={savingCategory || !newCategoryName.trim()}>
                      {savingCategory ? <Loader2 className="h-4 w-4 animate-spin" /> : "Create"}
                    </Button>
                  </div>
                </PopoverContent>
              </Popover>
            </div>
            {noticeCategories.length === 0 ? (
              <p className="py-8 text-center text-sm text-muted-foreground">No categories yet. Create one to start adding communications.</p>
            ) : (
              <div className="space-y-2">
                {noticeCategories.map((category) => {
                  const editing = editingCategory?.categories_uuid === category.categories_uuid;
                  return (
                    <div key={category.categories_uuid} className="flex items-center gap-2 rounded-md border p-2">
                      <Input
                        value={editing ? editingCategoryName : category.name}
                        readOnly={!editing}
                        onChange={(event) => setEditingCategoryName(event.target.value)}
                        className="border-0 bg-transparent shadow-none focus-visible:ring-0"
                      />
                      {editing ? (
                        <>
                          <Button type="button" size="sm" onClick={handleUpdateCategory} disabled={savingCategory || !editingCategoryName.trim()}>Save</Button>
                          <Button type="button" size="sm" variant="ghost" onClick={() => { setEditingCategory(null); setEditingCategoryName(""); }}>Cancel</Button>
                        </>
                      ) : (
                        <Button type="button" size="sm" variant="outline" onClick={() => { setEditingCategory(category); setEditingCategoryName(category.name); }}>Edit</Button>
                      )}
                      <Button type="button" size="icon" variant="ghost" className="text-destructive" disabled={savingCategory} onClick={() => handleDeleteCategory(category)} aria-label={`Delete ${category.name}`}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {workspaceTab === "communications" && (
      <>
      <Tabs value={activeTab} onValueChange={setActiveTab} className="mb-4">
        <TabsList className="h-auto flex-wrap justify-start">
          <TabsTrigger value="notices">
            <Megaphone className="mr-1.5 h-4 w-4" /> All Communications
          </TabsTrigger>
          {noticeCategories.map((category) => (
            <div key={category.categories_uuid} className="flex items-center rounded-md border">
              <TabsTrigger value={`category:${category.categories_uuid}`}>
                {category.name}
              </TabsTrigger>
              <Popover
                open={editingCategory?.categories_uuid === category.categories_uuid}
                onOpenChange={(open) => {
                  setEditingCategory(open ? category : null);
                  setEditingCategoryName(open ? category.name : "");
                }}
              >
                <PopoverTrigger asChild>
                  <Button
                    type="button"
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7"
                    aria-label={`Manage ${category.name} category`}
                    onClick={(event) => event.stopPropagation()}
                  >
                    <MoreHorizontal className="h-4 w-4" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-60 p-3" align="start">
                  <div className="flex flex-col gap-2">
                    <Label className="text-xs">Category name</Label>
                    <Input
                      value={editingCategoryName}
                      onChange={(event) => setEditingCategoryName(event.target.value)}
                      onKeyDown={(event) => {
                        if (event.key === "Enter") {
                          event.preventDefault();
                          handleUpdateCategory();
                        }
                      }}
                    />
                    <div className="flex justify-between gap-2">
                      <Button
                        type="button"
                        size="sm"
                        variant="destructive"
                        disabled={savingCategory}
                        onClick={() => handleDeleteCategory(category)}
                      >
                        Delete
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        disabled={savingCategory || !editingCategoryName.trim()}
                        onClick={handleUpdateCategory}
                      >
                        Save
                      </Button>
                    </div>
                  </div>
                </PopoverContent>
              </Popover>
            </div>
          ))}

          {/* Quick "add category" control — creates a category via the API and
              switches straight to its tab so a notice can be added under it. */}
          <Popover open={addingCategory} onOpenChange={setAddingCategory}>
            <PopoverTrigger asChild>
              <Button
                type="button"
                size="icon"
                variant="ghost"
                className="h-8 w-8 ml-1 shrink-0"
                aria-label="Add category"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-56 p-2" align="start">
              <div className="flex flex-col gap-2">
                <Label className="text-xs">New category</Label>
                <Input
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                  placeholder="Category name"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      handleCreateCategory();
                    }
                  }}
                />
                <Button
                  size="sm"
                  type="button"
                  onClick={handleCreateCategory}
                  disabled={savingCategory || !newCategoryName.trim()}
                >
                  {savingCategory ? (
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  ) : (
                    "Add"
                  )}
                </Button>
              </div>
            </PopoverContent>
          </Popover>
        </TabsList>
      </Tabs>

      {false ? (
        // ---------------- Academic Calendar: reference-style list ----------------
        <Card>
          <CardContent className="p-0">
            <div className="flex items-center justify-between px-5 py-4 border-b">
              <h3 className="text-base font-semibold">Academic Calendar</h3>
            </div>

            {loadingCalendar && (
              <div className="p-8 text-center text-sm text-muted-foreground flex items-center justify-center gap-2">
                <Loader2 className="h-4 w-4 animate-spin" />
                Loading academic calendar…
              </div>
            )}

            {!loadingCalendar && academicItems.length === 0 && (
              <div className="p-8 text-center text-sm text-muted-foreground">
                No academic calendar entries available yet.
              </div>
            )}

            {!loadingCalendar && academicItems.length > 0 && (
              <div className="divide-y">
                {academicItems.map((item) => {
                  const uuid = getCalendarUUID(item);
                  return (
                    <div
                      key={uuid}
                      className="flex items-start justify-between gap-4 px-5 py-4"
                    >
                      <div className="min-w-0">
                        <div className="text-xs text-muted-foreground">
                          {formatCalendarRange(item)}
                        </div>
                        <div className="text-base font-semibold mt-0.5">
                          {getCalendarTitle(item)}
                        </div>
                        {formatCalendarSubtitle(item) && (
                          <div className="text-xs text-muted-foreground mt-0.5">
                            {formatCalendarSubtitle(item)}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-2 shrink-0">
  <CalendarCategoryBadge category={getCalendarCategory(item)} />
  {getCalendarStatus(item) === "Draft" && (
    <Badge variant="outline" className="text-[10px]">
      Draft
    </Badge>
  )}

  <Popover
                          open={openMenuUUID === uuid}
                          onOpenChange={(o) => setOpenMenuUUID(o ? uuid : null)}
                        >
                          <PopoverTrigger asChild>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-8 w-8"
                              disabled={deletingUUID === uuid}
                            >
                              {deletingUUID === uuid ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <MoreHorizontal className="h-4 w-4" />
                              )}
                            </Button>
                          </PopoverTrigger>
                        <PopoverContent align="end" className="w-40 p-1">
                            <button
                              type="button"
                              className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-muted/60 transition-colors"
                              onClick={() => openEditCalendar(item)}
                            >
                              <Pencil className="h-3.5 w-3.5" />
                              Edit
                            </button>
                            <button
                              type="button"
                              className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm text-destructive hover:bg-destructive/10 transition-colors"
                              onClick={() => handleDeleteCalendar(item)}
                            >
                              <Trash2 className="h-3.5 w-3.5" />
                              Delete
                            </button>
                          </PopoverContent>
                        </Popover>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      ) : (
        // ---------------- Notices / Events / Holidays: unchanged style ----------------
        <Card>
          <CardContent className="p-0 divide-y">
            <div className="flex justify-end px-5 py-3">
              <RowsPerPageSelect {...noticesPage} />
            </div>
            {!listLoading && displayList.length === 0 && (
              <div className="p-8 text-center text-sm text-muted-foreground">
                No {sectionLabel.toLowerCase()}s available yet.
              </div>
            )}

            {listLoading && (
              <div className="p-8 text-center text-sm text-muted-foreground">
                Loading {sectionLabel.toLowerCase()}s…
              </div>
            )}
            {!listLoading && noticesPage.pageItems.map((n) => (
              <div key={getItemUUID(n)} className="p-3 hover:bg-muted/30">
                <div className="flex items-start gap-3">
                  <div className="h-9 w-9 rounded-md flex items-center justify-center bg-info/10 text-info shrink-0">
                    <Megaphone className="h-4 w-4" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm font-medium">{getItemTitle(n)}</span>
                      <Badge variant="outline" className="text-[10px]">
                        {getItemCategory(n)}
                      </Badge>
                      <Badge variant="secondary" className="text-[10px]">
                        {getItemAudience(n)}
                        {getItemTargetClass(n) ? ` · ${getItemTargetClass(n)}` : ""}
                      </Badge>
                      <Badge
                        variant={getItemStatus(n) === "Published" ? "default" : "outline"}
                        className="text-[10px]"
                      >
                        {getItemStatus(n)}
                      </Badge>

                      <Popover
                        open={openMenuUUID === getItemUUID(n)}
                        onOpenChange={(o) =>
                          setOpenMenuUUID(o ? getItemUUID(n) : null)
                        }
                      >
                        <PopoverTrigger asChild>
                          <Button
                            size="icon"
                            variant="ghost"
                            className="h-6 w-6 ml-auto"
                            disabled={deletingItemUUID === getItemUUID(n)}
                          >
                            {deletingItemUUID === getItemUUID(n) ? (
                              <Loader2 className="h-3.5 w-3.5 animate-spin" />
                            ) : (
                              <MoreHorizontal className="h-3.5 w-3.5" />
                            )}
                          </Button>
                        </PopoverTrigger>
                        <PopoverContent align="end" className="w-36 p-1">
                          <button
                            type="button"
                            className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-muted/60 transition-colors"
                            onClick={() => openEditItem(n)}
                          >
                            <Pencil className="h-3.5 w-3.5" />
                            Edit
                          </button>
                          <button
                            type="button"
                            disabled={togglingItemUUID === getItemUUID(n)}
                            className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-muted/60 transition-colors disabled:cursor-not-allowed disabled:opacity-50"
                            onClick={() => handleToggleItemPublish(n)}
                          >
                            {getItemStatus(n) === "Published" ? (
                              <EyeOff className="h-3.5 w-3.5" />
                            ) : (
                              <Send className="h-3.5 w-3.5" />
                            )}
                            {getItemStatus(n) === "Published" ? "Unpublish" : "Publish"}
                          </button>
                          <button
                            type="button"
                            className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm text-destructive hover:bg-destructive/10 transition-colors"
                            onClick={() => handleDeleteItem(n)}
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                            Delete
                          </button>
                        </PopoverContent>
                      </Popover>
                    </div>
                    {(n.start_date ?? n.startDate) && (
                      <div className="text-[11px] text-muted-foreground mt-0.5">
                        {n.start_date ?? new Date(n.startDate).toISOString().slice(0, 10)}
                        {(n.end_date ?? n.endDate) &&
                        (n.end_date ?? n.endDate) !== (n.start_date ?? n.startDate)
                          ? ` to ${n.end_date ?? new Date(n.endDate).toISOString().slice(0, 10)}`
                          : ""}
                      </div>
                    )}
                  <div className="text-xs mt-1 line-clamp-2">{getItemBody(n)}</div>

                 {getItemAttachments(n).length > 0 && (
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {getItemAttachments(n).map((att, idx) => (
                          <div
                            key={idx}
                            className="flex items-center gap-1 rounded-md border px-2 py-1 text-[11px] bg-muted/20"
                          >
                            {att.type?.startsWith("image/") ? (
                              <ImageIcon className="h-3 w-3" />
                            ) : att.type?.startsWith("video/") ? (
                              <Video className="h-3 w-3" />
                            ) : (
                              <FileText className="h-3 w-3" />
                            )}
                            <span className="truncate max-w-[140px]">
                              {att.name}
                            </span>
                            {att.url ? <>
                              <button
                                type="button"
                                title={`View ${att.name}`}
                                onClick={() => openAttachmentPreview(att)}
                                className="ml-1 rounded p-0.5 hover:bg-muted"
                              >
                                <Eye className="h-3.5 w-3.5" />
                              </button>
                              <a
                                href={att.url}
                                download={att.name}
                                title={`Download ${att.name}`}
                                className="rounded p-0.5 hover:bg-muted"
                              >
                                <Download className="h-3.5 w-3.5" />
                              </a>
                            </> : <EyeOff className="ml-1 h-3.5 w-3.5 text-muted-foreground" />}
                          </div>
                        ))}
                      </div>
                    )}

                    <div className="flex items-center gap-2 mt-2">
                      <Button
                        size="sm"
                        variant="outline"
                        className="h-8 gap-1.5 text-xs"
                        disabled={togglingItemUUID === getItemUUID(n)}
                        onClick={() => handleToggleItemPublish(n)}
                      >
                        {togglingItemUUID === getItemUUID(n) ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : getItemStatus(n) === "Published" ? (
                          <EyeOff className="h-3.5 w-3.5" />
                        ) : (
                          <Send className="h-3.5 w-3.5" />
                        )}
                        {getItemStatus(n) === "Published" ? "Unpublish" : "Publish"}
                      </Button>
                    </div>

                  </div>
                </div>
              </div>
            ))}
            <PaginationBar {...noticesPage} itemLabel={sectionLabel.toLowerCase() + "s"} showPageSize={false} />
          </CardContent>
        </Card>
      )}
      </>
      )}

      {/* Attachment preview — view a document/image/video inline instead of
          only being able to open it in a new tab or download it blind. */}
      <Dialog open={!!previewAttachment} onOpenChange={(o) => !o && setPreviewAttachment(null)}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 pr-6">
              {previewAttachment && getFileKind(previewAttachment) === "image" && (
                <ImageIcon className="h-4 w-4 shrink-0" />
              )}
              {previewAttachment && getFileKind(previewAttachment) === "video" && (
                <Video className="h-4 w-4 shrink-0" />
              )}
              {previewAttachment && getFileKind(previewAttachment) === "pdf" && (
                <FileText className="h-4 w-4 shrink-0" />
              )}
              {previewAttachment && getFileKind(previewAttachment) === "other" && (
                <FileText className="h-4 w-4 shrink-0" />
              )}
              <span className="truncate">{previewAttachment?.name || "Attachment"}</span>
            </DialogTitle>
          </DialogHeader>

          {previewAttachment && (
            <div className="space-y-3">
              <div className="rounded-md border bg-muted/20 flex items-center justify-center overflow-hidden min-h-[200px] max-h-[70vh]">
                {getFileKind(previewAttachment) === "image" && (
                  <img
                    src={previewAttachment.url}
                    alt={previewAttachment.name}
                    className="max-h-[70vh] w-auto object-contain"
                  />
                )}
                {getFileKind(previewAttachment) === "video" && (
                  <video
                    src={previewAttachment.url}
                    controls
                    autoPlay={false}
                    className="max-h-[70vh] w-full"
                  />
                )}
                {getFileKind(previewAttachment) === "pdf" && (
                  <iframe
                    src={previewAttachment.url}
                    title={previewAttachment.name}
                    className="w-full h-[70vh]"
                  />
                )}
                {getFileKind(previewAttachment) === "other" && (
                  <div className="flex flex-col items-center gap-2 p-8 text-sm text-muted-foreground">
                    <FileText className="h-8 w-8" />
                    No inline preview available for this file type.
                  </div>
                )}
              </div>

              <DialogFooter className="sm:justify-between">
                <Button
                  variant="ghost"
                  onClick={() => setPreviewAttachment(null)}
                >
                  Close
                </Button>
                <a
                  href={previewAttachment.url}
                  download={previewAttachment.name}
                  target="_blank"
                  rel="noreferrer"
                >
                  <Button variant="outline" className="gap-1.5">
                    <Download className="h-4 w-4" />
                    Download
                  </Button>
                </a>
              </DialogFooter>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

